insert into lesson (id, ordinal, title_en, title_it, grammar_points, video_id) values
  ('が-が示す主語', 1, 'The subject with が, and the three kinds of predicate', 'Il soggetto con が e i tre tipi di predicato', array['「が」が示す主語', '述語の三つの形'], 'pSvH9vH60Ig'),
  ('ゼロ代名詞', 2, 'The unwritten subject (zero pronoun), and the object with を', 'Il soggetto sottinteso (pronome zero) e l''oggetto con を', array['ゼロ代名詞', '「を」で示す目的語'], 'P3n8n0u3LHA'),
  ('は-が示す主題', 3, 'The topic with は, and the destination with に', 'Il tema con は e la destinazione con に', array['「は」が示す主題', '到達点を示す「に」'], 'U9_T4eObNXg'),
  ('非過去形', 4, 'Verb tenses: future or habit, happening now, past; time words with or without に', 'I tempi del verbo: futuro o abitudine, azione in corso, passato; le parole di tempo con o senza に', array['非過去形', '「ている」の進行', '過去形の「た」', '時を示す「に」'], 'lU5rmrAORDY'),
  ('動詞の三つのグループ', 5, 'The three verb groups and how to make the て and た forms', 'I tre gruppi di verbi e come si fanno le forme in て e in た', array['動詞の三つのグループ', 'て形・た形の作り方'], 'GzEVLMDC8nw'),
  ('名詞を修飾する述語', 6, 'Describing a noun: adjectives, verbs, な and の', 'Descrivere un nome: aggettivi, verbi, な e の', array['名詞を修飾する述語', '名詞を修飾する「な」', '名詞を修飾する「の」'], 'iyVZlaEqU24'),
  ('否定の-ない', 7, 'Saying "not": ない and ません', 'Dire «non»: ない e ません', array['否定の「ない」', '名詞文の否定「ではない」', '形容詞の否定「くない」', '丁寧な否定「ません」'], 'KIPhvGxp43c'),
  ('動詞の語幹と助動詞', 8, 'The verb stem and its auxiliaries (ます, たい, せる, れる, よう)', 'Il radicale del verbo e i suoi ausiliari (ます, たい, せる, れる, よう)', array['動詞の語幹と助動詞', '連用形につく「ます」「たい」', '未然形につく「せる」「れる」', '意向形'], 'FhyrskGBKHE'),
  ('目的地を示す-に', 9, 'The particle に (where you go, why, where something is, what it becomes) and へ', 'La particella に (dove si va, per fare cosa, dove si trova, cosa diventa) e へ', array['目的地を示す「に」', '目的を示す「に」', '存在の場所を示す「に」', '変化の結果を示す「に」', '方向を示す「へ」'], 'uqlQYrE2oFM'),
  ('動作の場所を示す-で', 10, 'で for the place of an action and for the means; と to join nouns', 'で per il luogo di un''azione e per il mezzo; と per unire i nomi', array['動作の場所を示す「で」', '手段を示す「で」', '名詞をつなぐ「と」'], 'dwcTI9qvO-U'),
  ('感情-理解の述語と-が', 11, 'Likes, understanding and wishes with が; がる for other people''s feelings', 'Gusti, capire e desideri con が; がる per i sentimenti degli altri', array['感情・理解の述語と「が」', '欲求の「ほしい」と「たい」', '他人の感情を示す「がる」'], 'vk3aKqMQwhM'),
  ('可能形', 12, 'The potential form ("can do") and できる', 'La forma potenziale («posso fare») e できる', array['可能形', '不規則動詞の可能形', '可能形と「が」'], 'qcOhHmU0znI'),
  ('て形で節をつなぐ', 13, 'The te-form to join actions; favours with てくれる and てあげる', 'La forma in て per unire le azioni; i favori con てくれる e てあげる', array['て形で節をつなぐ', '恩恵を受ける「てくれる」', '恩恵を与える「てあげる」'], '3X2ZCWazrDw')
on conflict (id) do update set
  ordinal = excluded.ordinal,
  title_en = excluded.title_en,
  title_it = excluded.title_it,
  grammar_points = excluded.grammar_points,
  video_id = excluded.video_id;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('57975a13-e0c2-5eda-9d3f-5bb832248016', 'が-が示す主語', 'assemble', '{"sentence":{"kanji":"妹が毎朝歌います","kana":"いもうとがまいあさうたいます"},"answer":["妹が","毎朝","歌います"],"prompt":{"en":"Build: \"My younger sister sings every morning.\"","it":"Componi: «Mia sorella minore canta ogni mattina.»"},"translation":{"en":"My younger sister sings every morning.","it":"Mia sorella minore canta ogni mattina."},"glosses":[{"text":"妹が","reading":"いもうとが","meaning":{"en":"younger sister (subject)","it":"sorella minore (soggetto)"}},{"text":"毎朝","reading":"まいあさ","meaning":{"en":"every morning","it":"ogni mattina"}},{"text":"歌います","reading":"うたいます","meaning":{"en":"sings","it":"canta"}}]}'::jsonb, '「が」が示す主語', 'が marks the subject: the one who does the action (here 妹, younger sister). The predicate, the part that says something about the subject, is 歌います (sings). 毎朝 (every morning) only says when, so it takes no が.', 'が segna il soggetto: chi compie l''azione (qui 妹, la sorella minore). Il predicato, cioè la parte che dice qualcosa del soggetto, è 歌います (canta). 毎朝 (ogni mattina) dice solo quando, quindi non prende が.'),
  ('2e47b85b-29ba-54d7-a09a-2533decd1cb3', 'が-が示す主語', 'select-span', '{"sentence":{"kanji":"妹が学生だ","kana":"いもうとががくせいだ"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part means \"is\"?","it":"Quale parte vuol dire «è»?"},"translation":{"en":"My younger sister is a student.","it":"Mia sorella minore è una studentessa."},"glosses":[{"text":"妹が学生","meaning":{"en":"younger sister (subject) + student","it":"sorella minore (soggetto) + studentessa"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '述語の三つの形', 'だ means "is". It works like "is" in "my sister is a student": it links the subject (妹) to a noun (学生, student). A predicate ends in one of three ways: a verb, a noun + だ, or an い-adjective.', 'だ vuol dire «è». Funziona come «è» in «mia sorella è una studentessa»: collega il soggetto (妹) a un nome (学生, studentessa). Un predicato finisce in uno di tre modi: con un verbo, con un nome + だ, oppure con un aggettivo in い.'),
  ('8347f682-389b-5c65-81af-6af0f0424823', 'が-が示す主語', 'single-select', '{"sentence":{"kanji":"水が冷たい","kana":"みずがつめたい"},"answer":"冷たい","distractors":["冷たいだ","冷だ","冷たくだ"],"gap":{"kanji":"水が＿","kana":"みずが＿"},"prompt":{"en":"\"The water is cold.\" Which predicate is correct?","it":"«L''acqua è fredda.» Qual è il predicato giusto?"},"translation":{"en":"The water is cold.","it":"L''acqua è fredda."},"glosses":[{"text":"冷たい","reading":"つめたい"},{"text":"冷たいだ","reading":"つめたいだ"},{"text":"冷だ","reading":"つめだ"},{"text":"冷たくだ","reading":"つめたくだ"}]}'::jsonb, '述語の三つの形', 'An い-adjective (an adjective that ends in い, like 冷たい) already contains "is": 冷たい means "is cold". So you never add だ ("is") after it. 冷だ and 冷たくだ do not exist.', 'Un aggettivo in い (un aggettivo che finisce in い, come 冷たい) contiene già «è»: 冷たい vuol dire «è freddo». Per questo dopo non si aggiunge mai だ («è»). 冷だ e 冷たくだ non esistono.'),
  ('95f788c5-e8de-5ee0-939f-ccb14bb33878', 'が-が示す主語', 'single-select', '{"sentence":{"kanji":"犬が走る","kana":"いぬがはしる"},"answer":"が","distractors":["を","の"],"gap":{"kanji":"犬＿走る","kana":"いぬ＿はしる"},"prompt":{"en":"\"The dog runs.\" Which particle marks who runs?","it":"«Il cane corre.» Quale particella segna chi corre?"},"translation":{"en":"The dog runs.","it":"Il cane corre."}}'::jsonb, '「が」が示す主語', 'A particle is a small word after a noun that shows its role in the sentence. The dog is the one who runs, so it is the subject and takes が. を would make the dog the thing something is done to, and の joins two nouns ("the dog''s …"), but here a verb follows.', 'Una particella è una piccola parola dopo un nome che ne indica il ruolo nella frase. Il cane è chi corre, quindi è il soggetto e prende が. を farebbe del cane la cosa su cui si agisce, e の unisce due nomi («il … del cane»), ma qui segue un verbo.'),
  ('96417561-b8b2-5859-a24b-bd3424eb35df', 'が-が示す主語', 'single-select', '{"sentence":{"kanji":"鳥が飛ぶ","kana":"とりがとぶ"},"answer":"飛ぶ","distractors":["飛ぶだ","飛びだ"],"gap":{"kanji":"鳥が＿","kana":"とりが＿"},"prompt":{"en":"\"The bird flies.\" Which predicate is correct?","it":"«L''uccello vola.» Qual è il predicato giusto?"},"translation":{"en":"The bird flies.","it":"L''uccello vola."},"glosses":[{"text":"飛ぶ","reading":"とぶ"},{"text":"飛ぶだ","reading":"とぶだ"},{"text":"飛びだ","reading":"とびだ"}]}'::jsonb, '述語の三つの形', 'A verb (a word for an action, like 飛ぶ, "to fly") is a complete predicate on its own. だ ("is") goes after a noun, never after a verb. So the sentence simply ends with 飛ぶ.', 'Un verbo (una parola che indica un''azione, come 飛ぶ, «volare») è da solo un predicato completo. だ («è») va dopo un nome, mai dopo un verbo. Quindi la frase finisce semplicemente con 飛ぶ.'),
  ('02123de7-b2e5-585e-ac74-e6acd9887a28', 'が-が示す主語', 'single-select', '{"sentence":{"kanji":"母が先生だ","kana":"ははがせんせいだ"},"answer":"だ","distractors":["が","を"],"gap":{"kanji":"母が先生＿","kana":"ははがせんせい＿"},"prompt":{"en":"\"My mother is a teacher.\" What goes at the end?","it":"«Mia madre è un''insegnante.» Che cosa va alla fine?"},"translation":{"en":"My mother is a teacher.","it":"Mia madre è un''insegnante."}}'::jsonb, '述語の三つの形', '先生 (teacher) is a noun, and a noun needs だ ("is") to become a predicate: 先生だ means "is a teacher". が and を are particles: they mark the role of a noun and cannot end the sentence.', '先生 (insegnante) è un nome, e un nome ha bisogno di だ («è») per diventare un predicato: 先生だ vuol dire «è un''insegnante». が e を sono particelle: indicano il ruolo di un nome e non possono chiudere la frase.'),
  ('ad39360b-8249-53f5-9c12-9470d788e82e', 'が-が示す主語', 'select-span', '{"sentence":{"kanji":"バスが来た","kana":"バスがきた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the subject?","it":"Quale parte è il soggetto?"},"translation":{"en":"The bus came.","it":"L''autobus è arrivato."},"glosses":[{"text":"バスが","meaning":{"en":"the bus (subject)","it":"l''autobus (soggetto)"}},{"text":"来","reading":"き","meaning":{"en":"come (kanji of 来る)","it":"venire (kanji di 来る)"}},{"text":"た","meaning":{"en":"past-tense ending","it":"desinenza del passato"}}]}'::jsonb, '「が」が示す主語', 'The subject is バスが: the bus is what came. が comes right after the subject and marks it. 来た (came) is the predicate, the part that says what the subject did.', 'Il soggetto è バスが: l''autobus è ciò che è arrivato. が viene subito dopo il soggetto e lo segna. 来た (è arrivato) è il predicato, la parte che dice che cosa ha fatto il soggetto.'),
  ('088b4f0c-3fc5-559c-a9eb-1f3423da41a7', 'が-が示す主語', 'select-span', '{"sentence":{"kanji":"スープが熱い","kana":"スープがあつい"},"answer":{"start":0,"end":1},"prompt":{"en":"What is hot? Select the subject.","it":"Che cosa è caldo? Seleziona il soggetto."},"translation":{"en":"The soup is hot.","it":"La zuppa è calda."},"glosses":[{"text":"スープが","meaning":{"en":"the soup (subject)","it":"la zuppa (soggetto)"}},{"text":"熱","reading":"あつ","meaning":{"en":"hot (kanji of 熱い)","it":"caldo (kanji di 熱い)"}},{"text":"い","meaning":{"en":"ending of the い-adjective","it":"finale dell''aggettivo in い"}}]}'::jsonb, '「が」が示す主語', 'The subject is スープが: the soup is what is hot. Here the predicate is 熱い ("is hot"), an い-adjective (an adjective that ends in い). It takes its subject with が, just like a verb does.', 'Il soggetto è スープが: la zuppa è ciò che è caldo. Qui il predicato è 熱い («è caldo»), un aggettivo in い (un aggettivo che finisce in い). Prende il soggetto con が, proprio come un verbo.'),
  ('4ccc8886-e854-5c55-a092-0969d474f1f1', 'が-が示す主語', 'assemble', '{"sentence":{"kanji":"兄が医者だ","kana":"あにがいしゃだ"},"answer":["兄が","医者","だ"],"prompt":{"en":"Build: \"My older brother is a doctor.\"","it":"Componi: «Mio fratello maggiore è medico.»"},"translation":{"en":"My older brother is a doctor.","it":"Mio fratello maggiore è medico."},"glosses":[{"text":"兄が","reading":"あにが","meaning":{"en":"older brother (subject)","it":"fratello maggiore (soggetto)"}},{"text":"医者","reading":"いしゃ","meaning":{"en":"doctor","it":"medico"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '述語の三つの形', 'The subject 兄 (older brother) comes first, with が. Then comes the noun 医者 (doctor) and だ, the word for "is" that links the subject to that noun. In Japanese the predicate always comes last.', 'Il soggetto 兄 (fratello maggiore) viene per primo, con が. Poi il nome 医者 (medico) e だ, la parola per «è» che collega il soggetto a quel nome. In giapponese il predicato va sempre alla fine.'),
  ('f18bbdf2-9a07-56f2-98e2-bf2125774963', 'が-が示す主語', 'assemble', '{"sentence":{"kanji":"この店のラーメンがおいしい","kana":"このみせのラーメンがおいしい"},"answer":["この","店の","ラーメンが","おいしい"],"prompt":{"en":"Build: \"The ramen at this restaurant is delicious.\"","it":"Componi: «Il ramen di questo locale è buonissimo.»"},"translation":{"en":"The ramen at this restaurant is delicious.","it":"Il ramen di questo locale è buonissimo."},"glosses":[{"text":"この","meaning":{"en":"this","it":"questo"}},{"text":"店の","reading":"みせの","meaning":{"en":"of the restaurant","it":"del locale"}},{"text":"ラーメンが","meaning":{"en":"ramen (subject)","it":"ramen (soggetto)"}},{"text":"おいしい","meaning":{"en":"is delicious (い-adjective)","it":"è buonissimo (aggettivo in い)"}}]}'::jsonb, '述語の三つの形', 'The subject is ラーメン, marked by が; この店の ("of this restaurant") comes before it and describes it. The predicate is おいしい, an い-adjective (an adjective that ends in い) that already means "is delicious". So no だ follows it.', 'Il soggetto è ラーメン, segnato da が; この店の («di questo locale») viene prima e lo descrive. Il predicato è おいしい, un aggettivo in い (un aggettivo che finisce in い) che vuol già dire «è buonissimo». Per questo dopo non c''è だ.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('0f32d14b-3435-526b-bbac-b35ac5c7db99', 'ゼロ代名詞', 'assemble', '{"sentence":{"kanji":"弟がパンを焼く","kana":"おとうとがパンをやく"},"answer":["弟が","パンを","焼く"],"prompt":{"en":"Build: \"My younger brother bakes bread.\"","it":"Componi: «Mio fratello minore cuoce il pane.»"},"translation":{"en":"My younger brother bakes bread.","it":"Mio fratello minore cuoce il pane."},"glosses":[{"text":"弟が","reading":"おとうとが","meaning":{"en":"younger brother (subject)","it":"fratello minore (soggetto)"}},{"text":"パンを","meaning":{"en":"bread (object)","it":"pane (oggetto)"}},{"text":"焼く","reading":"やく","meaning":{"en":"bakes","it":"cuoce"}}]}'::jsonb, '「を」で示す目的語', 'が marks the subject: who does the action (弟, younger brother). を marks the object: the thing the action is done to (パン, bread). The verb 焼く (bakes) comes last.', 'が segna il soggetto: chi compie l''azione (弟, il fratello minore). を segna l''oggetto: la cosa su cui si compie l''azione (パン, il pane). Il verbo 焼く (cuoce) va alla fine.'),
  ('3ac7b3aa-91eb-55f4-bd8b-99d8c49f8990', 'ゼロ代名詞', 'select-span', '{"sentence":{"kanji":"ピザを焼いた","kana":"ピザをやいた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the object (the thing the action is done to)?","it":"Quale parte è l''oggetto (la cosa su cui si compie l''azione)?"},"translation":{"en":"(I) baked a pizza.","it":"(Io) ho cotto una pizza."},"glosses":[{"text":"ピザを","meaning":{"en":"pizza (object)","it":"pizza (oggetto)"}},{"text":"焼","reading":"や","meaning":{"en":"bake (kanji of 焼く)","it":"cuocere (kanji di 焼く)"}},{"text":"いた","meaning":{"en":"past-tense ending of 焼く","it":"desinenza del passato di 焼く"}}]}'::jsonb, '「を」で示す目的語', 'The object is ピザを: を marks the pizza as the thing that was baked. The subject is not written, yet the sentence is complete: it is a zero pronoun, a subject that is left out but understood. With no other context it is the speaker: "I baked a pizza".', 'L''oggetto è ピザを: を segna la pizza come la cosa che è stata cotta. Il soggetto non è scritto, eppure la frase è completa: è un pronome zero, cioè un soggetto non scritto ma sottinteso. Senza altro contesto è chi parla: «ho cotto una pizza».'),
  ('aa3360be-653c-52cd-bcc5-aacdbd09a332', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"猫が魚を食べた","kana":"ねこがさかなをたべた"},"answer":"を","distractors":["が","の"],"gap":{"kanji":"猫が魚＿食べた","kana":"ねこがさかな＿たべた"},"prompt":{"en":"\"The cat ate the fish.\" Which particle marks what was eaten?","it":"«Il gatto ha mangiato il pesce.» Quale particella segna ciò che è stato mangiato?"},"translation":{"en":"The cat ate the fish.","it":"Il gatto ha mangiato il pesce."}}'::jsonb, '「を」で示す目的語', 'The fish is what gets eaten, so it is the object and takes を. が is already on 猫 (cat), the one who eats. の joins two nouns ("the fish''s …"), but here a verb follows.', 'Il pesce è ciò che viene mangiato, quindi è l''oggetto e prende を. が è già su 猫 (il gatto), chi mangia. の unisce due nomi («il … del pesce»), ma qui segue un verbo.'),
  ('0cde5b10-898c-581d-9750-a83dbf5ad084', 'ゼロ代名詞', 'select-span', '{"sentence":{"kanji":"もう八時だ","kana":"もうはちじだ"},"answer":{"start":2,"end":3},"prompt":{"en":"No subject is written. Which part means \"is\"?","it":"Il soggetto non è scritto. Quale parte vuol dire «è»?"},"translation":{"en":"It''s already eight o''clock.","it":"Sono già le otto."},"glosses":[{"text":"もう","meaning":{"en":"already","it":"già"}},{"text":"八時","reading":"はちじ","meaning":{"en":"eight o''clock","it":"le otto"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, 'ゼロ代名詞', 'だ means "is": 八時だ means "(it) is eight o''clock". No subject is written, and none is needed: the subject is a zero pronoun, left out but understood. Here the situation makes it clear: the current time.', 'だ vuol dire «è»: 八時だ vuol dire «sono le otto». Il soggetto non è scritto, e non serve: è un pronome zero, cioè un soggetto sottinteso. Qui lo chiarisce la situazione: l''ora attuale.'),
  ('e9ac22ea-8073-5d03-a921-43dbccd1614e', 'ゼロ代名詞', 'assemble', '{"sentence":{"kanji":"毎晩日記を書く","kana":"まいばんにっきをかく"},"answer":["毎晩","日記を","書く"],"prompt":{"en":"Build: \"(I) write in my diary every night.\"","it":"Componi: «(Io) scrivo il diario ogni sera.»"},"translation":{"en":"(I) write in my diary every night.","it":"(Io) scrivo il diario ogni sera."},"glosses":[{"text":"毎晩","reading":"まいばん","meaning":{"en":"every night","it":"ogni sera"}},{"text":"日記を","reading":"にっきを","meaning":{"en":"diary (object)","it":"diario (oggetto)"}},{"text":"書く","reading":"かく","meaning":{"en":"write","it":"scrivo"}}]}'::jsonb, 'ゼロ代名詞', 'There is no が, yet someone is writing. The subject of 書く (write) is a zero pronoun: not written, but understood. With no other context it is the speaker: "I write…".', 'Non c''è nessun が, eppure qualcuno scrive. Il soggetto di 書く (scrivere) è un pronome zero: non è scritto, ma è sottinteso. Senza altro contesto è chi parla: «(io) scrivo…».'),
  ('579c5b10-3119-59bc-8ed4-87dd1c948f35', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"窓を開ける","kana":"まどをあける"},"answer":"を","distractors":["が","で"],"gap":{"kanji":"窓＿開ける","kana":"まど＿あける"},"prompt":{"en":"\"(I) open the window.\" Which particle marks the window?","it":"«(Io) apro la finestra.» Quale particella segna la finestra?"},"translation":{"en":"(I) open the window.","it":"(Io) apro la finestra."}}'::jsonb, 'ゼロ代名詞', '窓 (window) is the thing being opened, so it is the object and takes を. With が the window would become the subject, the one doing the opening. The real subject, the person who opens it, is a zero pronoun: not written but understood ("I").', '窓 (finestra) è la cosa che viene aperta, quindi è l''oggetto e prende を. Con が la finestra diventerebbe il soggetto, cioè chi apre. Il vero soggetto, la persona che apre, è un pronome zero: non è scritto ma è sottinteso («io»).'),
  ('e6a8429c-f309-59ac-b715-e0021dc6bbf1', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"母が手紙を読んだ","kana":"ははがてがみをよんだ"},"answer":"を","distractors":["が","で"],"gap":{"kanji":"母が手紙＿読んだ","kana":"ははがてがみ＿よんだ"},"prompt":{"en":"\"My mother read the letter.\" Which particle marks what was read?","it":"«Mia madre ha letto la lettera.» Quale particella segna ciò che è stato letto?"},"translation":{"en":"My mother read the letter.","it":"Mia madre ha letto la lettera."}}'::jsonb, '「を」で示す目的語', 'The letter is the thing being read, so it is the object and takes を. が is already on 母 (mother), the one who reads. で marks the place or the means of an action ("at", "with"), not the thing that is read.', 'La lettera è la cosa che viene letta, quindi è l''oggetto e prende を. が è già su 母 (la madre), chi legge. で indica il luogo o il mezzo dell''azione («in», «con»), non la cosa letta.'),
  ('86643edb-f4c4-5d4c-9ff6-3bfd9ec2df0f', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"顔を洗った","kana":"かおをあらった"},"answer":"を","distractors":["が","に"],"gap":{"kanji":"顔＿洗った","kana":"かお＿あらった"},"prompt":{"en":"\"(I) washed my face.\" Which particle goes after 顔 (face)?","it":"«(Io) mi sono lavato la faccia.» Quale particella va dopo 顔 (faccia)?"},"translation":{"en":"(I) washed my face.","it":"(Io) mi sono lavato la faccia."}}'::jsonb, 'ゼロ代名詞', 'The face is the thing being washed, so it takes を, the particle of the object. The one who washes is not written: it is a zero pronoun, understood from the context (here, the speaker). With が, the face itself would be doing the washing, which makes no sense.', 'La faccia è la cosa che viene lavata, quindi prende を, la particella dell''oggetto. Chi lava non è scritto: è un pronome zero, sottinteso dal contesto (qui, chi parla). Con が sarebbe la faccia stessa a lavare, e non ha senso.'),
  ('d55bbe36-3e6d-5b4d-b98f-2ddcf45e4e0b', 'ゼロ代名詞', 'select-span', '{"sentence":{"kanji":"このカメラを買った","kana":"このカメラをかった"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the object?","it":"Quale parte è l''oggetto?"},"translation":{"en":"(I) bought this camera.","it":"(Io) ho comprato questa macchina fotografica."},"glosses":[{"text":"このカメラを","meaning":{"en":"this camera (object)","it":"questa macchina fotografica (oggetto)"}},{"text":"買","reading":"か","meaning":{"en":"buy (kanji of 買う)","it":"comprare (kanji di 買う)"}},{"text":"った","meaning":{"en":"past-tense ending","it":"desinenza del passato"}}]}'::jsonb, '「を」で示す目的語', 'The object is このカメラを: the camera is the thing that was bought, and を comes right after it. The one who bought it is not written; with no other context it is the speaker: "I bought this camera".', 'L''oggetto è このカメラを: la macchina fotografica è la cosa comprata, e を viene subito dopo. Chi l''ha comprata non è scritto; senza altro contesto è chi parla: «ho comprato questa macchina fotografica».'),
  ('fc98755a-2a0e-5e18-9ab8-71ae24c76328', 'ゼロ代名詞', 'assemble', '{"sentence":{"kanji":"いつもラジオを聞く","kana":"いつもラジオをきく"},"answer":["いつも","ラジオを","聞く"],"prompt":{"en":"Build: \"(I) always listen to the radio.\"","it":"Componi: «(Io) ascolto sempre la radio.»"},"translation":{"en":"(I) always listen to the radio.","it":"(Io) ascolto sempre la radio."},"glosses":[{"text":"いつも","meaning":{"en":"always","it":"sempre"}},{"text":"ラジオを","meaning":{"en":"radio (object)","it":"radio (oggetto)"}},{"text":"聞く","reading":"きく","meaning":{"en":"listen","it":"ascolto"}}]}'::jsonb, 'ゼロ代名詞', 'No subject is written: the one who listens is a zero pronoun, understood as the speaker. ラジオ (radio) is the object, so it takes を, and the verb 聞く (listen) comes last. いつも (always) only says how often.', 'Il soggetto non è scritto: chi ascolta è un pronome zero, sottinteso come chi parla. ラジオ (radio) è l''oggetto, quindi prende を, e il verbo 聞く (ascoltare) va alla fine. いつも (sempre) dice solo quanto spesso.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('18239c82-53c0-5b50-b5ea-1ea27f2ef47b', 'は-が示す主題', 'select-span', '{"sentence":{"kanji":"これは私の傘だ","kana":"これはわたしのかさだ"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the topic (what the sentence is about)?","it":"Quale parte è il tema (ciò di cui si parla)?"},"translation":{"en":"This is my umbrella.","it":"Questo è il mio ombrello."},"glosses":[{"text":"これは","meaning":{"en":"this (topic)","it":"questo (tema)"}},{"text":"私の傘","reading":"わたしのかさ","meaning":{"en":"my umbrella","it":"il mio ombrello"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '「は」が示す主題', 'The topic is これは: は marks what the sentence is about, "as for this…". は does not say who does what; it only announces the topic. The rest, 私の傘だ, says something about it: "is my umbrella".', 'Il tema è これは: は segna ciò di cui parla la frase, «quanto a questo…». は non dice chi fa che cosa: annuncia solo l''argomento. Il resto, 私の傘だ, dice qualcosa del tema: «è il mio ombrello».'),
  ('4a486ed2-e831-53d7-bb03-619e7e55f5e5', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"東京は人が多い","kana":"とうきょうはひとがおおい"},"answer":"は","distractors":["を","へ"],"gap":{"kanji":"東京＿人が多い","kana":"とうきょう＿ひとがおおい"},"prompt":{"en":"\"As for Tokyo, there are many people.\" Which particle marks Tokyo?","it":"«Quanto a Tokyo, ci sono molte persone.» Quale particella segna Tokyo?"},"translation":{"en":"As for Tokyo, there are many people.","it":"Quanto a Tokyo, ci sono molte persone."}}'::jsonb, '「は」が示す主題', 'Tokyo is not the subject: what is "many" is the people, 人, already marked by が. Tokyo is the topic, what the sentence is about ("as for Tokyo"), and the topic takes は. を marks an object and へ a direction; neither fits here.', 'Tokyo non è il soggetto: a essere molte sono le persone (人), già segnate da が. Tokyo è il tema, ciò di cui si parla («quanto a Tokyo»), e il tema prende は. を segna un oggetto e へ una direzione: qui non vanno bene.'),
  ('8bd02c8c-712f-5b02-950e-c60858e8f452', 'は-が示す主題', 'assemble', '{"sentence":{"kanji":"私は毎日コーヒーを飲む","kana":"わたしはまいにちコーヒーをのむ"},"answer":["私は","毎日","コーヒーを","飲む"],"prompt":{"en":"Build: \"I drink coffee every day.\" Start with the topic.","it":"Componi: «Bevo caffè ogni giorno.» Comincia dal tema."},"translation":{"en":"I drink coffee every day.","it":"Bevo caffè ogni giorno."},"glosses":[{"text":"私は","reading":"わたしは","meaning":{"en":"I (topic)","it":"io (tema)"}},{"text":"毎日","reading":"まいにち","meaning":{"en":"every day","it":"ogni giorno"}},{"text":"コーヒーを","meaning":{"en":"coffee (object)","it":"caffè (oggetto)"}},{"text":"飲む","reading":"のむ","meaning":{"en":"drink","it":"bevo"}}]}'::jsonb, '「は」が示す主題', '私は is the topic: "as for me". は says what the sentence is about, not who does the action; here it is simply clear that I am the one who drinks. コーヒー (coffee) is the object, so it takes を.', '私は è il tema: «quanto a me». は dice di che cosa parla la frase, non chi compie l''azione; qui è semplicemente chiaro che sono io a bere. コーヒー (caffè) è l''oggetto, quindi prende を.'),
  ('61e926e3-590c-5339-9425-120cfbbb25da', 'は-が示す主題', 'select-span', '{"sentence":{"kanji":"ポストに手紙を入れた","kana":"ポストにてがみをいれた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says where the letter ends up?","it":"Quale parte dice dove finisce la lettera?"},"translation":{"en":"(I) put the letter in the postbox.","it":"(Io) ho messo la lettera nella buca delle lettere."},"glosses":[{"text":"ポストに","meaning":{"en":"into the postbox (destination)","it":"nella buca (destinazione)"}},{"text":"手紙を入","reading":"てがみをい","meaning":{"en":"letter (object), 入 of 入れる","it":"lettera (oggetto), 入 di 入れる"}},{"text":"れた","meaning":{"en":"rest of 入れた (past)","it":"resto di 入れた (passato)"}}]}'::jsonb, '到達点を示す「に」', 'The answer is ポストに. に marks the destination: the place where the action ends up (here, inside the postbox). The letter is the object, with を.', 'La risposta è ポストに. に segna la destinazione: il punto in cui l''azione va a finire (qui, dentro la buca delle lettere). La lettera è l''oggetto, con を.'),
  ('f1d776a4-259a-5651-914b-90de125c1c1c', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"先生に花をあげた","kana":"せんせいにはなをあげた"},"answer":"に","distractors":["を","で"],"gap":{"kanji":"先生＿花をあげた","kana":"せんせい＿はなをあげた"},"prompt":{"en":"\"I gave flowers to the teacher.\" Which particle marks the person who receives them?","it":"«Ho dato dei fiori all''insegnante.» Quale particella segna chi li riceve?"},"translation":{"en":"I gave flowers to the teacher.","it":"Ho dato dei fiori all''insegnante."}}'::jsonb, '到達点を示す「に」', 'The teacher is the person the flowers go to. に marks where something arrives, and that includes a person who receives it. 花 (flowers) is the thing given, so it already has を.', 'L''insegnante è la persona a cui vanno i fiori. に segna dove arriva qualcosa, anche quando è una persona che lo riceve. 花 (fiori) è la cosa data, quindi ha già を.'),
  ('34bfcd4c-14f4-5e5a-86c3-764f90e7c57a', 'は-が示す主題', 'assemble', '{"sentence":{"kanji":"姉が友達に手紙を送った","kana":"あねがともだちにてがみをおくった"},"answer":["姉が","友達に","手紙を","送った"],"prompt":{"en":"Build: \"My older sister sent a letter to a friend.\"","it":"Componi: «Mia sorella maggiore ha spedito una lettera a un amico.»"},"translation":{"en":"My older sister sent a letter to a friend.","it":"Mia sorella maggiore ha spedito una lettera a un amico."},"glosses":[{"text":"姉が","reading":"あねが","meaning":{"en":"older sister (subject)","it":"sorella maggiore (soggetto)"}},{"text":"友達に","reading":"ともだちに","meaning":{"en":"to a friend","it":"a un amico"}},{"text":"手紙を","reading":"てがみを","meaning":{"en":"letter (object)","it":"lettera (oggetto)"}},{"text":"送った","reading":"おくった","meaning":{"en":"sent","it":"ha spedito"}}]}'::jsonb, '到達点を示す「に」', 'Each particle shows a role: が who sends (姉, older sister), に who the letter goes to (友達, a friend), を what is sent (手紙, a letter). Because the particles show the roles, 手紙を could also come before 友達に with the same meaning; here we use the most common order.', 'Ogni particella indica un ruolo: が chi spedisce (姉, la sorella maggiore), に a chi va la lettera (友達, un amico), を che cosa si spedisce (手紙, una lettera). Poiché i ruoli li danno le particelle, 手紙を potrebbe anche venire prima di 友達に con lo stesso significato; qui usiamo l''ordine più comune.'),
  ('1e706b10-234a-58f5-8475-806e623c27ab', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"この本は高い","kana":"このほんはたかい"},"answer":"は","distractors":["を","に"],"gap":{"kanji":"この本＿高い","kana":"このほん＿たかい"},"prompt":{"en":"\"This book is expensive.\" Which particle marks what the sentence is about?","it":"«Questo libro è caro.» Quale particella segna ciò di cui si parla?"},"translation":{"en":"This book is expensive.","it":"Questo libro è caro."}}'::jsonb, '「は」が示す主題', 'The sentence is about this book, so この本 is the topic and takes は. The predicate 高い ("is expensive") then says something about it. を marks an object and に a destination: neither goes with an adjective like 高い.', 'La frase parla di questo libro, quindi この本 è il tema e prende は. Il predicato 高い («è caro») dice poi qualcosa del tema. を segna un oggetto e に una destinazione: nessuna delle due va con un aggettivo come 高い.'),
  ('569f7a67-1ab8-53bf-9b64-7e06448425b4', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"駅に着いた","kana":"えきについた"},"answer":"に","distractors":["を","で"],"gap":{"kanji":"駅＿着いた","kana":"えき＿ついた"},"prompt":{"en":"\"(I) arrived at the station.\" Which particle marks where (I) arrived?","it":"«(Io) sono arrivato alla stazione.» Quale particella segna dove sono arrivato?"},"translation":{"en":"(I) arrived at the station.","it":"(Io) sono arrivato alla stazione."}}'::jsonb, '到達点を示す「に」', 'The station is where the movement ends, its destination, so it takes に. With を the station would be the thing acted on. で marks where an action takes place, not where you arrive.', 'La stazione è il punto in cui finisce lo spostamento, la destinazione, quindi prende に. Con を la stazione sarebbe la cosa su cui si agisce. で indica dove si svolge un''azione, non dove si arriva.'),
  ('8bef3929-c4d1-519e-9b36-6a254724d7d3', 'は-が示す主題', 'select-span', '{"sentence":{"kanji":"テストは明日だ","kana":"テストはあしただ"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says what the sentence is about?","it":"Quale parte dice di che cosa parla la frase?"},"translation":{"en":"The test is tomorrow.","it":"L''esame è domani."},"glosses":[{"text":"テストは","meaning":{"en":"the test (topic)","it":"l''esame (tema)"}},{"text":"明日","reading":"あした","meaning":{"en":"tomorrow","it":"domani"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '「は」が示す主題', 'The topic is テストは: the sentence is about the test, and は marks it. The rest, 明日だ, says something about the topic: "is tomorrow". だ is the word for "is" that links the topic to a noun (明日, tomorrow).', 'Il tema è テストは: la frase parla dell''esame, e は lo segna. Il resto, 明日だ, dice qualcosa del tema: «è domani». だ è la parola per «è» che collega il tema a un nome (明日, domani).'),
  ('6065d965-6f9e-5372-972d-4eb4310df00f', 'は-が示す主題', 'assemble', '{"sentence":{"kanji":"子どもが部屋に入った","kana":"こどもがへやにはいった"},"answer":["子どもが","部屋に","入った"],"prompt":{"en":"Build: \"The child went into the room.\"","it":"Componi: «Il bambino è entrato nella stanza.»"},"translation":{"en":"The child went into the room.","it":"Il bambino è entrato nella stanza."},"glosses":[{"text":"子どもが","reading":"こどもが","meaning":{"en":"the child (subject)","it":"il bambino (soggetto)"}},{"text":"部屋に","reading":"へやに","meaning":{"en":"into the room (destination)","it":"nella stanza (destinazione)"}},{"text":"入った","reading":"はいった","meaning":{"en":"went in","it":"è entrato"}}]}'::jsonb, '到達点を示す「に」', 'が marks the subject, the one who moves (子ども, child). に marks the destination, the place where the movement ends (部屋, room). The verb 入った (went in) comes last.', 'が segna il soggetto, chi si muove (子ども, il bambino). に segna la destinazione, il luogo in cui finisce lo spostamento (部屋, la stanza). Il verbo 入った (è entrato) va alla fine.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('b7d38cc8-562b-59dd-92df-b6599109a919', '非過去形', 'single-select', '{"sentence":{"kanji":"明日は雨が降る","kana":"あしたはあめがふる"},"answer":"降る","distractors":["降った","降っていた"],"gap":{"kanji":"明日は雨が＿","kana":"あしたはあめが＿"},"prompt":{"en":"\"It will rain tomorrow.\" Which verb form fits?","it":"«Domani pioverà.» Quale forma del verbo è giusta?"},"translation":{"en":"It will rain tomorrow.","it":"Domani pioverà."},"glosses":[{"text":"降る","reading":"ふる"},{"text":"降った","reading":"ふった"},{"text":"降っていた","reading":"ふっていた"}]}'::jsonb, '非過去形', '降る is the dictionary form (the basic form of the verb, the one you find in a dictionary). It is a non-past tense: it covers the future and habits, not only "now". With 明日 (tomorrow) it means "it will rain"; a past form like 降った cannot go with tomorrow.', '降る è la forma del dizionario (la forma base del verbo, quella che trovi sul dizionario). È un tempo non passato: vale per il futuro e per le abitudini, non solo per «adesso». Con 明日 (domani) significa «pioverà»; un passato come 降った non può stare con domani.'),
  ('3ed770d8-53e8-583b-9402-cdba8605fcb4', '非過去形', 'single-select', '{"sentence":{"kanji":"父が新聞を読んでいる","kana":"ちちがしんぶんをよんでいる"},"answer":"読んでいる","distractors":["読むいる","読みている","読んいる"],"gap":{"kanji":"父が新聞を＿","kana":"ちちがしんぶんを＿"},"prompt":{"en":"\"My father is reading the newspaper.\" Which form says the action is happening right now?","it":"«Mio padre sta leggendo il giornale.» Quale forma dice che l''azione sta succedendo adesso?"},"translation":{"en":"My father is reading the newspaper.","it":"Mio padre sta leggendo il giornale."},"glosses":[{"text":"読んでいる","reading":"よんでいる"},{"text":"読むいる","reading":"よむいる"},{"text":"読みている","reading":"よみている"},{"text":"読んいる","reading":"よんいる"}]}'::jsonb, '「ている」の進行', '"Is doing" = te-form + いる. The te-form is the verb form ending in て or で (読む → 読んで). So 読んでいる means "is reading"; いる never attaches directly to 読む or 読み.', '«Sta facendo» = forma in て + いる. La forma in て è la forma del verbo che finisce in て o で (読む → 読んで). Quindi 読んでいる significa «sta leggendo»; いる non si attacca mai direttamente a 読む o a 読み.'),
  ('3b4b6752-0757-51a1-b94d-13f807ec11e8', '非過去形', 'select-span', '{"sentence":{"kanji":"妹がテレビを見ている","kana":"いもうとがテレビをみている"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part shows that the action is happening right now?","it":"Quale parte indica che l''azione sta succedendo adesso?"},"translation":{"en":"My younger sister is watching TV.","it":"Mia sorella minore sta guardando la TV."},"glosses":[{"text":"妹がテレビを見","reading":"いもうとがテレビをみ","meaning":{"en":"younger sister, TV, watch","it":"sorella minore, TV, guardare"}},{"text":"ている","meaning":{"en":"is ...-ing (happening now)","it":"sta ...-ndo (succede adesso)"}}]}'::jsonb, '「ている」の進行', 'Select ている. 見る (to watch) just drops る to make its te-form (the form ending in て): 見て. Add いる and you get 見ている, "is watching".', 'Seleziona ている. 見る (guardare) toglie solo る per fare la forma in て (la forma che finisce in て): 見て. Aggiungi いる e ottieni 見ている, «sta guardando».'),
  ('2281b09b-cfa1-5201-b30a-a4d0e9916bdd', '非過去形', 'select-span', '{"sentence":{"kanji":"昨日カレーを作った","kana":"きのうカレーをつくった"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part makes the verb past?","it":"Quale parte mette il verbo al passato?"},"translation":{"en":"(I) made curry yesterday.","it":"Ieri (io) ho preparato il curry."},"glosses":[{"text":"昨日カレーを作","reading":"きのうカレーをつく","meaning":{"en":"yesterday, curry, make","it":"ieri, curry, preparare"}},{"text":"った","meaning":{"en":"past ending","it":"desinenza del passato"}}]}'::jsonb, '過去形の「た」', 'Select った. The past is built like the te-form (the form ending in て), just with た instead of て: 作る → 作って → 作った. 昨日 (yesterday) needs no particle.', 'Seleziona った. Il passato si costruisce come la forma in て (la forma che finisce in て), solo con た al posto di て: 作る → 作って → 作った. 昨日 (ieri) non vuole particella.'),
  ('5f4f76f1-97eb-5e69-b160-43aaeca96e13', '非過去形', 'assemble', '{"sentence":{"kanji":"先週新しい靴を買った","kana":"せんしゅうあたらしいくつをかった"},"answer":["先週","新しい","靴を","買った"],"prompt":{"en":"Build: \"I bought new shoes last week.\"","it":"Componi: «La settimana scorsa ho comprato delle scarpe nuove.»"},"translation":{"en":"I bought new shoes last week.","it":"La settimana scorsa ho comprato delle scarpe nuove."},"glosses":[{"text":"先週","reading":"せんしゅう","meaning":{"en":"last week","it":"la settimana scorsa"}},{"text":"新しい","reading":"あたらしい","meaning":{"en":"new","it":"nuove"}},{"text":"靴を","reading":"くつを","meaning":{"en":"shoes (what I bought)","it":"scarpe (cosa ho comprato)"}},{"text":"買った","reading":"かった","meaning":{"en":"bought","it":"ho comprato"}}]}'::jsonb, '過去形の「た」', 'The time word 先週 (last week) goes first, with no particle. Then "new shoes" + を (the particle that marks what you buy), then the verb at the end. 買う → 買った (bought).', 'La parola di tempo 先週 (la settimana scorsa) va per prima, senza particella. Poi «scarpe nuove» + を (la particella che indica cosa compri), poi il verbo in fondo. 買う → 買った (ho comprato).'),
  ('4af79a02-6a52-5ed0-8de8-d892d154cd92', '非過去形', 'assemble', '{"sentence":{"kanji":"七時に友達が来る","kana":"しちじにともだちがくる"},"answer":["七時に","友達が","来る"],"prompt":{"en":"Build: \"A friend is coming at seven.\"","it":"Componi: «Alle sette viene un amico.»"},"translation":{"en":"A friend is coming at seven.","it":"Alle sette viene un amico."},"glosses":[{"text":"七時に","reading":"しちじに","meaning":{"en":"at seven o''clock","it":"alle sette"}},{"text":"友達が","reading":"ともだちが","meaning":{"en":"a friend (the one who comes)","it":"un amico (chi viene)"}},{"text":"来る","reading":"くる","meaning":{"en":"comes","it":"viene"}}]}'::jsonb, '時を示す「に」', 'A clock time like 七時 (seven o''clock) takes に, like English "at". Quick test: if English says "at", "on" or "in" before the time, Japanese uses に. 来る (comes) is non-past, so here it means a future arrival.', 'Un orario come 七時 (le sette) prende に, come «alle» in italiano. Prova rapida: se in inglese davanti al tempo serve «at», «on» o «in», in giapponese serve に. 来る (viene) è non passato, quindi qui indica un arrivo futuro.'),
  ('1362ab6a-c76c-52f2-8990-3d5c04dced59', '非過去形', 'single-select', '{"sentence":{"kanji":"来年大学を卒業する","kana":"らいねんだいがくをそつぎょうする"},"answer":"来年","distractors":["来年を","来年が"],"gap":{"kanji":"＿大学を卒業する","kana":"＿だいがくをそつぎょうする"},"prompt":{"en":"\"I will graduate from university next year.\" How is \"next year\" written here?","it":"«L''anno prossimo mi laureo.» Come si scrive qui «l''anno prossimo»?"},"translation":{"en":"I will graduate from university next year.","it":"L''anno prossimo mi laureo."},"glosses":[{"text":"来年","reading":"らいねん"},{"text":"来年を","reading":"らいねんを"},{"text":"来年が","reading":"らいねんが"}]}'::jsonb, '時を示す「に」', '来年 (next year) depends on when you are speaking, so it takes no particle. に is only for fixed times, like a date, a weekday or an hour. With を or が, 来年 would become the thing you finish, or the one who graduates.', '来年 (l''anno prossimo) dipende da quando parli, quindi non prende particella. に serve solo per i tempi fissi, come una data, un giorno della settimana o un''ora. Con を o が, 来年 diventerebbe la cosa che finisci, o chi si laurea.'),
  ('77a06afc-5205-501e-9734-bdbd9ec37ba5', '非過去形', 'select-span', '{"sentence":{"kanji":"きのう雨が降った","kana":"きのうあめがふった"},"answer":{"start":0,"end":1},"prompt":{"en":"Which word says when it rained?","it":"Quale parola dice quando è piovuto?"},"translation":{"en":"It rained yesterday.","it":"Ieri è piovuto."},"glosses":[{"text":"きのう","meaning":{"en":"yesterday","it":"ieri"}},{"text":"雨が降","reading":"あめがふ","meaning":{"en":"rain, fall","it":"pioggia, cadere"}},{"text":"った","meaning":{"en":"past ending","it":"desinenza del passato"}}]}'::jsonb, '時を示す「に」', 'Select きのう (yesterday). Words like yesterday, today, tomorrow or last week depend on when you are speaking, so they take no に. They simply sit at the start of the sentence.', 'Seleziona きのう (ieri). Parole come ieri, oggi, domani o la settimana scorsa dipendono da quando parli, quindi non prendono に. Stanno semplicemente all''inizio della frase.'),
  ('0cb772a1-ec27-552f-854c-7daf8ed5c783', '非過去形', 'assemble', '{"sentence":{"kanji":"毎朝コーヒーを飲む","kana":"まいあさコーヒーをのむ"},"answer":["毎朝","コーヒーを","飲む"],"prompt":{"en":"Build: \"I drink coffee every morning.\"","it":"Componi: «Ogni mattina bevo il caffè.»"},"translation":{"en":"I drink coffee every morning.","it":"Ogni mattina bevo il caffè."},"glosses":[{"text":"毎朝","reading":"まいあさ","meaning":{"en":"every morning","it":"ogni mattina"}},{"text":"コーヒーを","meaning":{"en":"coffee (what I drink)","it":"caffè (cosa bevo)"}},{"text":"飲む","reading":"のむ","meaning":{"en":"drink","it":"bevo"}}]}'::jsonb, '非過去形', 'For a habit, use the non-past: the verb exactly as a dictionary lists it, 飲む, "I drink". 毎朝 (every morning) takes no に and goes first; the verb always comes last.', 'Per un''abitudine si usa il non passato: il verbo così come lo trovi sul dizionario, 飲む, «bevo». 毎朝 (ogni mattina) non prende に e va per primo; il verbo sta sempre in fondo.'),
  ('68eb3381-1ff9-5c34-b388-6f5da586e7ea', '非過去形', 'assemble', '{"sentence":{"kanji":"姉は今電話で話している","kana":"あねはいまでんわではなしている"},"answer":["姉は","今","電話で","話している"],"prompt":{"en":"Build: \"My older sister is talking on the phone now.\"","it":"Componi: «Mia sorella maggiore adesso sta parlando al telefono.»"},"translation":{"en":"My older sister is talking on the phone now.","it":"Mia sorella maggiore adesso sta parlando al telefono."},"glosses":[{"text":"姉は","reading":"あねは","meaning":{"en":"my older sister (the topic)","it":"mia sorella maggiore (l''argomento)"}},{"text":"今","reading":"いま","meaning":{"en":"now","it":"adesso"}},{"text":"電話で","reading":"でんわで","meaning":{"en":"on the phone","it":"al telefono"}},{"text":"話している","reading":"はなしている","meaning":{"en":"is talking","it":"sta parlando"}}]}'::jsonb, '「ている」の進行', '話す (to talk) has the te-form (the form ending in て) 話して; adding いる gives 話している, "is talking". 今 (now) takes no particle. The verb goes last.', '話す (parlare) ha la forma in て (la forma che finisce in て) 話して; aggiungendo いる si ottiene 話している, «sta parlando». 今 (adesso) non prende particella. Il verbo va in fondo.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('3edb0ae6-beb3-5405-a88e-42582289500c', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"朝ごはんを食べた","kana":"あさごはんをたべた"},"answer":"食べた","distractors":["食べった","食べいた","食んだ"],"gap":{"kanji":"朝ごはんを＿","kana":"あさごはんを＿"},"prompt":{"en":"\"I ate breakfast.\" What is the past of 食べる?","it":"«Ho fatto colazione.» Qual è il passato di 食べる?"},"translation":{"en":"I ate breakfast.","it":"Ho fatto colazione."},"glosses":[{"text":"食べた","reading":"たべた"},{"text":"食べった","reading":"たべった"},{"text":"食べいた","reading":"たべいた"},{"text":"食んだ","reading":"たんだ"}]}'::jsonb, '動詞の三つのグループ', '食べる is an ichidan verb (the group of verbs ending in -iru or -eru that simply drop る). To make the past, drop る and add た: 食べ + た = 食べた. Nothing else changes.', '食べる è un verbo ichidan (il gruppo di verbi in -iru o -eru che tolgono semplicemente る). Per fare il passato togli る e aggiungi た: 食べ + た = 食べた. Non cambia nient''altro.'),
  ('d5c8da5e-6e1b-5e48-b374-a114cb6e4e43', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"毎朝公園を走っている","kana":"まいあさこうえんをはしっている"},"answer":"走って","distractors":["走て","走りて","走んで"],"gap":{"kanji":"毎朝公園を＿いる","kana":"まいあさこうえんを＿いる"},"prompt":{"en":"\"I run in the park every morning.\" What is the te-form of 走る?","it":"«Ogni mattina corro al parco.» Qual è la forma in て di 走る?"},"translation":{"en":"I run in the park every morning.","it":"Ogni mattina corro al parco."},"glosses":[{"text":"走って","reading":"はしって"},{"text":"走て","reading":"はして"},{"text":"走りて","reading":"はしりて"},{"text":"走んで","reading":"はしんで"}]}'::jsonb, '動詞の三つのグループ', '走る ends in -iru, but it is a godan verb (the group of verbs whose last syllable changes, like 書く → 書いて). Godan verbs ending in る make the te-form (the form ending in て) with a small っ: 走る → 走って. 走て is wrong: that would treat it like 食べる.', '走る finisce in -iru, ma è un verbo godan (il gruppo di verbi che cambiano l''ultima sillaba, come 書く → 書いて). I godan in る fanno la forma in て (la forma che finisce in て) con una piccola っ: 走る → 走って. 走て è sbagliato: lo tratterebbe come 食べる.'),
  ('cd298cc6-62a9-54aa-8f73-d88e3c6214f9', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"弟が薬を飲んだ","kana":"おとうとがくすりをのんだ"},"answer":"飲んだ","distractors":["飲った","飲いだ","飲みた"],"gap":{"kanji":"弟が薬を＿","kana":"おとうとがくすりを＿"},"prompt":{"en":"\"My younger brother took the medicine.\" What is the past of 飲む?","it":"«Mio fratello minore ha preso la medicina.» Qual è il passato di 飲む?"},"translation":{"en":"My younger brother took the medicine.","it":"Mio fratello minore ha preso la medicina."},"glosses":[{"text":"飲んだ","reading":"のんだ"},{"text":"飲った","reading":"のった"},{"text":"飲いだ","reading":"のいだ"},{"text":"飲みた","reading":"のみた"}]}'::jsonb, 'て形・た形の作り方', 'Verbs ending in む, ぶ or ぬ turn that syllable into ん, and て/た become で/だ. So 飲む (to drink) → 飲んで → 飲んだ.', 'I verbi che finiscono in む, ぶ o ぬ cambiano quella sillaba in ん, e て/た diventano で/だ. Quindi 飲む (bere) → 飲んで → 飲んだ.'),
  ('a83154b8-bddd-5726-ad4a-9cc36ddc9b02', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"昨日プールで泳いだ","kana":"きのうプールでおよいだ"},"answer":"泳いだ","distractors":["泳った","泳んだ","泳いた"],"gap":{"kanji":"昨日プールで＿","kana":"きのうプールで＿"},"prompt":{"en":"\"I swam in the pool yesterday.\" What is the past of 泳ぐ?","it":"«Ieri ho nuotato in piscina.» Qual è il passato di 泳ぐ?"},"translation":{"en":"I swam in the pool yesterday.","it":"Ieri ho nuotato in piscina."},"glosses":[{"text":"泳いだ","reading":"およいだ"},{"text":"泳った","reading":"およった"},{"text":"泳んだ","reading":"およんだ"},{"text":"泳いた","reading":"およいた"}]}'::jsonb, 'て形・た形の作り方', 'Verbs ending in く become いて/いた (書く → 書いた). Verbs ending in ぐ do the same, but with で/だ: いで/いだ. 泳ぐ (to swim) ends in ぐ, so the past is 泳いだ, not 泳いた.', 'I verbi che finiscono in く diventano いて/いた (書く → 書いた). Quelli in ぐ fanno lo stesso, ma con で/だ: いで/いだ. 泳ぐ (nuotare) finisce in ぐ, quindi il passato è 泳いだ, non 泳いた.'),
  ('5a77229e-6cec-5a7a-a56d-015085d4fd93', '動詞の三つのグループ', 'select-span', '{"sentence":{"kanji":"手紙を出した","kana":"てがみをだした"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part is the past ending of 出す?","it":"Quale parte è la desinenza del passato di 出す?"},"translation":{"en":"I sent a letter.","it":"Ho spedito una lettera."},"glosses":[{"text":"手紙を出","reading":"てがみをだ","meaning":{"en":"letter, send","it":"lettera, spedire"}},{"text":"した","meaning":{"en":"past ending of 出す (sent)","it":"desinenza del passato di 出す (spedito)"}}]}'::jsonb, 'て形・た形の作り方', 'Select した. Verbs ending in す change す into し, then add て or た: 出す (to send) → 出して → 出した.', 'Seleziona した. I verbi che finiscono in す cambiano す in し, poi aggiungono て o た: 出す (spedire) → 出して → 出した.'),
  ('10054a46-427c-5262-9c64-6c52b362676c', '動詞の三つのグループ', 'assemble', '{"sentence":{"kanji":"歩いて学校に行った","kana":"あるいてがっこうにいった"},"answer":["歩いて","学校に","行った"],"prompt":{"en":"Build: \"I walked to school.\"","it":"Componi: «Sono andato a scuola a piedi.»"},"translation":{"en":"I walked to school.","it":"Sono andato a scuola a piedi."},"glosses":[{"text":"歩いて","reading":"あるいて","meaning":{"en":"on foot, walking","it":"a piedi, camminando"}},{"text":"学校に","reading":"がっこうに","meaning":{"en":"to school","it":"a scuola"}},{"text":"行った","reading":"いった","meaning":{"en":"went","it":"sono andato"}}]}'::jsonb, 'て形・た形の作り方', '歩く (to walk) ends in く, so it becomes 歩いて ("walking"). 行く (to go) also ends in く, but it is the one exception: 行って / 行った, never 行いた. The te-form (the form ending in て) first says how you went.', '歩く (camminare) finisce in く, quindi diventa 歩いて («camminando»). Anche 行く (andare) finisce in く, ma è l''unica eccezione: 行って / 行った, mai 行いた. La forma in て (la forma che finisce in て) dice prima come sei andato.'),
  ('3b9faea7-4987-5660-b634-29e62290f61d', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"日曜日に友達が来た","kana":"にちようびにともだちがきた"},"answer":"来た","distractors":["来った","来いた","来んだ"],"gap":{"kanji":"日曜日に友達が＿","kana":"にちようびにともだちが＿"},"prompt":{"en":"\"A friend came on Sunday.\" What is the past of 来る?","it":"«Domenica è venuto un amico.» Qual è il passato di 来る?"},"translation":{"en":"A friend came on Sunday.","it":"Domenica è venuto un amico."},"glosses":[{"text":"来た","reading":"きた"},{"text":"来った","reading":"きった"},{"text":"来いた","reading":"きいた"},{"text":"来んだ","reading":"きんだ"}]}'::jsonb, '動詞の三つのグループ', 'Japanese has only two irregular verbs: 来る (to come) and する (to do). You just memorize their forms: 来る → 来て / 来た (read きて / きた), する → して / した.', 'Il giapponese ha solo due verbi irregolari: 来る (venire) e する (fare). Le loro forme si imparano a memoria: 来る → 来て / 来た (si leggono きて / きた), する → して / した.'),
  ('cc4c3df6-15b2-5fbe-b1f6-7dedc6204d86', '動詞の三つのグループ', 'select-span', '{"sentence":{"kanji":"バスを待った","kana":"バスをまった"},"answer":{"start":2,"end":3},"prompt":{"en":"Which part is the past ending of 待つ?","it":"Quale parte è la desinenza del passato di 待つ?"},"translation":{"en":"I waited for the bus.","it":"Ho aspettato l''autobus."},"glosses":[{"text":"バスを","meaning":{"en":"the bus (what I waited for)","it":"l''autobus (cosa ho aspettato)"}},{"text":"待","reading":"ま","meaning":{"en":"wait","it":"aspettare"}},{"text":"った","meaning":{"en":"past ending of 待つ (waited)","it":"desinenza del passato di 待つ (aspettato)"}}]}'::jsonb, 'て形・た形の作り方', 'Select った. Godan verbs (the group whose last syllable changes) ending in つ, う or る replace that syllable with a small っ, then add て or た. So 待つ (to wait) → 待って → 待った.', 'Seleziona った. I verbi godan (il gruppo che cambia l''ultima sillaba) che finiscono in つ, う o る sostituiscono quella sillaba con una piccola っ, poi aggiungono て o た. Quindi 待つ (aspettare) → 待って → 待った.'),
  ('64d5073f-f9b5-567d-84ed-235df78d0069', '動詞の三つのグループ', 'select-span', '{"sentence":{"kanji":"昨日は十時に寝た","kana":"きのうはじゅうじにねた"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part makes 寝る past?","it":"Quale parte mette 寝る al passato?"},"translation":{"en":"Yesterday I went to bed at ten.","it":"Ieri sono andato a letto alle dieci."},"glosses":[{"text":"昨日は十時に寝","reading":"きのうはじゅうじにね","meaning":{"en":"yesterday, at ten o''clock, go to bed","it":"ieri, alle dieci, andare a letto"}},{"text":"た","meaning":{"en":"past ending","it":"desinenza del passato"}}]}'::jsonb, '動詞の三つのグループ', 'Select た. 寝る (to go to bed) is an ichidan verb (it ends in -eru and simply drops る). So you drop る and add た: 寝 + た = 寝た. No small っ is needed.', 'Seleziona た. 寝る (andare a letto) è un verbo ichidan (finisce in -eru e toglie semplicemente る). Quindi togli る e aggiungi た: 寝 + た = 寝た. Non serve nessuna piccola っ.'),
  ('1b54d6fe-f1e5-50c8-b6e8-ba2152ccea72', '動詞の三つのグループ', 'assemble', '{"sentence":{"kanji":"本を読んで寝た","kana":"ほんをよんでねた"},"answer":["本を","読んで","寝た"],"prompt":{"en":"Build: \"I read a book and went to sleep.\"","it":"Componi: «Ho letto un libro e sono andato a dormire.»"},"translation":{"en":"I read a book and went to sleep.","it":"Ho letto un libro e sono andato a dormire."},"glosses":[{"text":"本を","reading":"ほんを","meaning":{"en":"a book (what I read)","it":"un libro (cosa ho letto)"}},{"text":"読んで","reading":"よんで","meaning":{"en":"read, and then","it":"ho letto, e poi"}},{"text":"寝た","reading":"ねた","meaning":{"en":"went to sleep","it":"sono andato a dormire"}}]}'::jsonb, 'て形・た形の作り方', 'The te-form (the form ending in て or で) joins two actions: "I did this, and then that". 読む ends in む, so it becomes 読んで. Only the last verb, 寝た, says that everything is in the past.', 'La forma in て (la forma che finisce in て o で) unisce due azioni: «ho fatto questo, e poi quello». 読む finisce in む, quindi diventa 読んで. Solo l''ultimo verbo, 寝た, dice che tutto è al passato.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('88bacd49-0013-53ad-8822-bc64198450cd', '名詞を修飾する述語', 'select-span', '{"sentence":{"kanji":"おいしい店に行った","kana":"おいしいみせにいった"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part describes the restaurant?","it":"Quale parte descrive il locale?"},"translation":{"en":"I went to a restaurant with delicious food.","it":"Sono andato in un locale dove si mangia bene."},"glosses":[{"text":"おいしい","meaning":{"en":"delicious","it":"buono, delizioso"}},{"text":"店に行","reading":"みせにい","meaning":{"en":"to the restaurant, go","it":"al locale, andare"}},{"text":"った","meaning":{"en":"past ending of 行く (went)","it":"desinenza del passato di 行く (andato)"}}]}'::jsonb, '名詞を修飾する述語', 'Select おいしい (delicious). It is an い-adjective (an adjective ending in い). To describe a noun, just put it right before the noun: おいしい店, "a restaurant with delicious food".', 'Seleziona おいしい (buono). È un aggettivo in い (un aggettivo che finisce in い). Per descrivere un nome basta metterlo subito prima del nome: おいしい店, «un locale dove si mangia bene».'),
  ('f514db52-f4fc-5d2f-af57-5ff12b9949c1', '名詞を修飾する述語', 'assemble', '{"sentence":{"kanji":"昨日買った傘が壊れた","kana":"きのうかったかさがこわれた"},"answer":["昨日","買った","傘が","壊れた"],"prompt":{"en":"Build: \"The umbrella I bought yesterday broke.\"","it":"Componi: «L''ombrello che ho comprato ieri si è rotto.»"},"translation":{"en":"The umbrella I bought yesterday broke.","it":"L''ombrello che ho comprato ieri si è rotto."},"glosses":[{"text":"昨日","reading":"きのう","meaning":{"en":"yesterday","it":"ieri"}},{"text":"買った","reading":"かった","meaning":{"en":"bought (describes the umbrella)","it":"comprato (descrive l''ombrello)"}},{"text":"傘が","reading":"かさが","meaning":{"en":"the umbrella (what broke)","it":"l''ombrello (cosa si è rotto)"}},{"text":"壊れた","reading":"こわれた","meaning":{"en":"broke","it":"si è rotto"}}]}'::jsonb, '名詞を修飾する述語', 'A verb can describe a noun too: put it right before the noun. 昨日買った傘 = "the umbrella (I) bought yesterday". Japanese needs no word for "that" or "which": the position is enough.', 'Anche un verbo può descrivere un nome: basta metterlo subito prima del nome. 昨日買った傘 = «l''ombrello (che) ho comprato ieri». Il giapponese non ha bisogno di una parola per «che»: basta la posizione.'),
  ('349ef8de-fce0-5138-84a5-10426df29fe8', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"静かな町に住んでいる","kana":"しずかなまちにすんでいる"},"answer":"静かな","distractors":["静かだ","静かの","静かい"],"gap":{"kanji":"＿町に住んでいる","kana":"＿まちにすんでいる"},"prompt":{"en":"\"I live in a quiet town.\" Which form of 静か goes before a noun?","it":"«Vivo in una città tranquilla.» Quale forma di 静か va davanti a un nome?"},"translation":{"en":"I live in a quiet town.","it":"Vivo in una città tranquilla."},"glosses":[{"text":"静かな","reading":"しずかな"},{"text":"静かだ","reading":"しずかだ"},{"text":"静かの","reading":"しずかの"},{"text":"静かい","reading":"しずかい"}]}'::jsonb, '名詞を修飾する「な」', '静か (quiet) is a な-adjective (an adjective that needs な before a noun). At the end of a sentence it takes だ ("is"): 町が静かだ, "the town is quiet". Before a noun, だ becomes な: 静かな町, "a quiet town".', '静か (tranquillo) è un aggettivo in な (un aggettivo che vuole な davanti a un nome). A fine frase prende だ (cioè «è»): 町が静かだ, «la città è tranquilla». Davanti a un nome, だ diventa な: 静かな町, «una città tranquilla».'),
  ('dfcc733a-c32e-5f45-9fd1-43b4c27d2055', '名詞を修飾する述語', 'assemble', '{"sentence":{"kanji":"有名な歌手が来た","kana":"ゆうめいなかしゅがきた"},"answer":["有名な","歌手が","来た"],"prompt":{"en":"Build: \"A famous singer came.\"","it":"Componi: «È venuto un cantante famoso.»"},"translation":{"en":"A famous singer came.","it":"È venuto un cantante famoso."},"glosses":[{"text":"有名な","reading":"ゆうめいな","meaning":{"en":"famous","it":"famoso"}},{"text":"歌手が","reading":"かしゅが","meaning":{"en":"a singer (the one who came)","it":"un cantante (chi è venuto)"}},{"text":"来た","reading":"きた","meaning":{"en":"came","it":"è venuto"}}]}'::jsonb, '名詞を修飾する「な」', '有名 (famous) is a な-adjective (an adjective that needs な before a noun), so: 有名な歌手, "a famous singer". Then が marks who did the action, and the verb 来た (came) goes last.', '有名 (famoso) è un aggettivo in な (un aggettivo che vuole な davanti a un nome), quindi: 有名な歌手, «un cantante famoso». Poi が indica chi ha fatto l''azione, e il verbo 来た (è venuto) va in fondo.'),
  ('79ae205c-615d-5647-9b01-d6800dee970c', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"木の机を買った","kana":"きのつくえをかった"},"answer":"の","distractors":["な","が"],"gap":{"kanji":"木＿机を買った","kana":"き＿つくえをかった"},"prompt":{"en":"\"I bought a wooden desk.\" Which particle links 木 to 机?","it":"«Ho comprato una scrivania di legno.» Quale particella collega 木 a 机?"},"translation":{"en":"I bought a wooden desk.","it":"Ho comprato una scrivania di legno."},"glosses":[{"text":"の"},{"text":"な"},{"text":"が"}]}'::jsonb, '名詞を修飾する「の」', '木 (wood) is a normal noun, not an adjective, so it cannot take な. When a noun describes another noun (whose it is, what it is made of, what kind it is), Japanese puts の between them: 木の机, "a desk of wood".', '木 (legno) è un nome normale, non un aggettivo, quindi non può prendere な. Quando un nome descrive un altro nome (di chi è, di che materiale è, di che tipo è), il giapponese mette の fra i due: 木の机, «una scrivania di legno».'),
  ('3be87963-5201-5b19-a2c5-b8b43bc26ea1', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"日本語の先生が来た","kana":"にほんごのせんせいがきた"},"answer":"の","distractors":["な","だ"],"gap":{"kanji":"日本語＿先生が来た","kana":"にほんご＿せんせいがきた"},"prompt":{"en":"\"The Japanese teacher came.\" Which particle links the two nouns?","it":"«È venuto l''insegnante di giapponese.» Quale particella collega i due nomi?"},"translation":{"en":"The Japanese teacher came.","it":"È venuto l''insegnante di giapponese."},"glosses":[{"text":"の"},{"text":"な"},{"text":"だ"}]}'::jsonb, '名詞を修飾する「の」', '日本語の先生 = "teacher of Japanese": の joins two nouns and says what kind of teacher. だ means "is" and goes at the end of a sentence, not between nouns. な is only for な-adjectives like 静か.', '日本語の先生 = «insegnante di giapponese»: の unisce due nomi e dice che tipo di insegnante è. だ vuol dire «è» e va a fine frase, non fra due nomi. な serve solo agli aggettivi in な come 静か.'),
  ('1f20e07c-7443-527b-9988-cd47e56ee9e9', '名詞を修飾する述語', 'select-span', '{"sentence":{"kanji":"きれいな花を買った","kana":"きれいなはなをかった"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part describes the flowers?","it":"Quale parte descrive i fiori?"},"translation":{"en":"I bought pretty flowers.","it":"Ho comprato dei bei fiori."},"glosses":[{"text":"きれいな","meaning":{"en":"pretty","it":"belli"}},{"text":"花を買","reading":"はなをか","meaning":{"en":"flowers, buy","it":"fiori, comprare"}},{"text":"った","meaning":{"en":"past ending of 買う (bought)","it":"desinenza del passato di 買う (comprato)"}}]}'::jsonb, '名詞を修飾する「な」', 'Select きれいな (pretty). きれい ends in い, but it is a な-adjective (an adjective that needs な before a noun), not an い-adjective. So before 花 (flowers) it becomes きれいな.', 'Seleziona きれいな (belli). きれい finisce in い, ma è un aggettivo in な (un aggettivo che vuole な davanti a un nome), non un aggettivo in い. Quindi davanti a 花 (fiori) diventa きれいな.'),
  ('b33f988e-8704-5ad9-92bf-12514e0cd894', '名詞を修飾する述語', 'select-span', '{"sentence":{"kanji":"あそこにいる人は先生だ","kana":"あそこにいるひとはせんせいだ"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part tells you which person we mean?","it":"Quale parte dice di quale persona si parla?"},"translation":{"en":"The person over there is a teacher.","it":"La persona laggiù è un insegnante."},"glosses":[{"text":"あそこにいる","meaning":{"en":"who is over there","it":"che è laggiù"}},{"text":"人は先生","reading":"ひとはせんせい","meaning":{"en":"person (the topic), teacher","it":"persona (l''argomento), insegnante"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '名詞を修飾する述語', 'Select あそこにいる ("is over there"). A verb placed right before a noun describes it: あそこにいる人 = "the person who is over there". At the end, だ is the word for "is": "...is a teacher".', 'Seleziona あそこにいる («è laggiù»). Un verbo messo subito prima di un nome lo descrive: あそこにいる人 = «la persona che è laggiù». In fondo, だ è la parola per «è»: «...è un insegnante».'),
  ('8f080662-e371-50cf-992a-a9e4560700e2', '名詞を修飾する述語', 'assemble', '{"sentence":{"kanji":"姉の車は赤い","kana":"あねのくるまはあかい"},"answer":["姉の","車は","赤い"],"prompt":{"en":"Build: \"My older sister''s car is red.\"","it":"Componi: «La macchina di mia sorella maggiore è rossa.»"},"translation":{"en":"My older sister''s car is red.","it":"La macchina di mia sorella maggiore è rossa."},"glosses":[{"text":"姉の","reading":"あねの","meaning":{"en":"my older sister''s","it":"di mia sorella maggiore"}},{"text":"車は","reading":"くるまは","meaning":{"en":"the car (the topic)","it":"la macchina (l''argomento)"}},{"text":"赤い","reading":"あかい","meaning":{"en":"is red","it":"è rossa"}}]}'::jsonb, '名詞を修飾する「の」', '姉の車 = "my older sister''s car": の goes after the owner, and the owner comes before the thing. Then は marks what we talk about, and 赤い (red) closes the sentence: an い-adjective alone already means "is red".', '姉の車 = «la macchina di mia sorella maggiore»: の va dopo chi possiede, e chi possiede viene prima della cosa. Poi は indica di cosa si parla, e 赤い (rosso) chiude la frase: un aggettivo in い da solo significa già «è rosso».'),
  ('9b92691c-3dbe-5d5f-90c2-1338b5fa7cee', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"新しい服を買った","kana":"あたらしいふくをかった"},"answer":"新しい","distractors":["新しいな","新しいの","新しいだ"],"gap":{"kanji":"＿服を買った","kana":"＿ふくをかった"},"prompt":{"en":"\"I bought new clothes.\" Which form of 新しい goes before 服?","it":"«Ho comprato dei vestiti nuovi.» Quale forma di 新しい va davanti a 服?"},"translation":{"en":"I bought new clothes.","it":"Ho comprato dei vestiti nuovi."},"glosses":[{"text":"新しい","reading":"あたらしい"},{"text":"新しいな","reading":"あたらしいな"},{"text":"新しいの","reading":"あたらしいの"},{"text":"新しいだ","reading":"あたらしいだ"}]}'::jsonb, '名詞を修飾する述語', '新しい (new) is an い-adjective (an adjective ending in い). It goes straight before the noun, with nothing in between: 新しい服, "new clothes". な is only for な-adjectives, and の only joins two nouns.', '新しい (nuovo) è un aggettivo in い (un aggettivo che finisce in い). Va direttamente davanti al nome, senza niente in mezzo: 新しい服, «vestiti nuovi». な serve solo agli aggettivi in な, e の unisce solo due nomi.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('de4b81da-1d12-5346-860e-ea0c1cad7e66', '否定の-ない', 'single-select', '{"sentence":{"kanji":"今日は時間がない","kana":"きょうはじかんがない"},"answer":"ない","distractors":["あらない","ないだ","なく"],"gap":{"kanji":"今日は時間が＿","kana":"きょうはじかんが＿"},"prompt":{"en":"\"I have no time today.\" How do you say \"there is not\" (the negative of ある)?","it":"«Oggi non ho tempo.» Come si dice «non c''è» (la negazione di ある)?"},"translation":{"en":"I have no time today.","it":"Oggi non ho tempo."},"glosses":[{"text":"ない"},{"text":"あらない"},{"text":"ないだ"},{"text":"なく"}]}'::jsonb, '否定の「ない」', 'ある ("there is") has an irregular negative: it is simply ない ("there is not"); あらない does not exist. ない is an い-adjective (a word that ends in い and already contains "is", like 高い = "is expensive"), so nothing goes after it: no だ ("is").', 'ある («c''è») ha una negazione irregolare: è semplicemente ない («non c''è»); あらない non esiste. ない è un aggettivo in い (una parola che finisce in い e contiene già il «è», come 高い = «è caro»), quindi dopo non vuole niente: niente だ («è»).'),
  ('b377835e-ce27-5345-8523-26d307f4fa86', '否定の-ない', 'single-select', '{"sentence":{"kanji":"兄はお酒を飲まない","kana":"あにはおさけをのまない"},"answer":"飲まない","distractors":["飲むない","飲みない","飲まらない"],"gap":{"kanji":"兄はお酒を＿","kana":"あにはおさけを＿"},"prompt":{"en":"\"My older brother doesn''t drink alcohol.\" How do you say \"doesn''t drink\" (from 飲む)?","it":"«Mio fratello maggiore non beve alcolici.» Come si dice «non beve» (da 飲む)?"},"translation":{"en":"My older brother doesn''t drink alcohol.","it":"Mio fratello maggiore non beve alcolici."},"glosses":[{"text":"飲まない","reading":"のまない"},{"text":"飲むない","reading":"のむない"},{"text":"飲みない","reading":"のみない"},{"text":"飲まらない","reading":"のまらない"}]}'::jsonb, '否定の「ない」', 'To make a verb negative, change its last kana from the u-sound to the a-sound, then add ない: 飲む → 飲ま + ない = 飲まない ("doesn''t drink"). You never put ない straight after the dictionary form: 飲むない is wrong.', 'Per negare un verbo si cambia l''ultimo kana dal suono u al suono a e poi si aggiunge ない: 飲む → 飲ま + ない = 飲まない («non beve»). ない non si mette mai direttamente dopo la forma base: 飲むない è sbagliato.'),
  ('42743f63-d12a-5fe3-845f-62a6c9511434', '否定の-ない', 'single-select', '{"sentence":{"kanji":"母は肉を買わない","kana":"はははにくをかわない"},"answer":"買わない","distractors":["買あない","買いない","買うない"],"gap":{"kanji":"母は肉を＿","kana":"はははにくを＿"},"prompt":{"en":"\"My mother doesn''t buy meat.\" How do you say \"doesn''t buy\" (from 買う)?","it":"«Mia madre non compra carne.» Come si dice «non compra» (da 買う)?"},"translation":{"en":"My mother doesn''t buy meat.","it":"Mia madre non compra carne."},"glosses":[{"text":"買わない","reading":"かわない"},{"text":"買あない","reading":"かあない"},{"text":"買いない","reading":"かいない"},{"text":"買うない","reading":"かうない"}]}'::jsonb, '否定の「ない」', 'Verbs ending in う are the one exception: before ない, う does not become あ but わ. So 買う ("to buy") → 買わ + ない = 買わない. 買あない does not exist.', 'I verbi che finiscono in う sono l''unica eccezione: davanti a ない, う non diventa あ ma わ. Quindi 買う («comprare») → 買わ + ない = 買わない. 買あない non esiste.'),
  ('15e5d9ee-259e-58fd-952b-2a29db6134f7', '否定の-ない', 'select-span', '{"sentence":{"kanji":"あれは駅ではない","kana":"あれはえきではない"},"answer":{"start":2,"end":3},"prompt":{"en":"\"That is not the station.\" Which part means \"is not\"?","it":"«Quella non è la stazione.» Quale parte significa «non è»?"},"translation":{"en":"That is not the station.","it":"Quella non è la stazione."},"glosses":[{"text":"あれは","meaning":{"en":"that one (は: the topic)","it":"quella (は: il tema)"}},{"text":"駅","reading":"えき","meaning":{"en":"station","it":"stazione"}},{"text":"ではない","meaning":{"en":"is not","it":"non è"}}]}'::jsonb, '名詞文の否定「ではない」', 'Select ではない ("is not"). After a noun, "is" is だ: 駅だ = "it is the station". To negate it, だ becomes ではない: 駅ではない; in casual speech people say じゃない.', 'Seleziona ではない («non è»). Dopo un nome, «è» si dice だ: 駅だ = «è la stazione». Per negarla, だ diventa ではない: 駅ではない; nel parlato informale si dice じゃない.'),
  ('ef8c40a5-800f-5e9f-a558-497b7536040a', '否定の-ない', 'single-select', '{"sentence":{"kanji":"この部屋は寒くない","kana":"このへやはさむくない"},"answer":"寒くない","distractors":["寒いない","寒いではない","寒じゃない"],"gap":{"kanji":"この部屋は＿","kana":"このへやは＿"},"prompt":{"en":"\"This room is not cold.\" How do you say \"is not cold\" (from 寒い)?","it":"«Questa stanza non è fredda.» Come si dice «non è fredda» (da 寒い)?"},"translation":{"en":"This room is not cold.","it":"Questa stanza non è fredda."},"glosses":[{"text":"寒くない","reading":"さむくない"},{"text":"寒いない","reading":"さむいない"},{"text":"寒いではない","reading":"さむいではない"},{"text":"寒じゃない","reading":"さむじゃない"}]}'::jsonb, '形容詞の否定「くない」', '寒い ("is cold") is an い-adjective: it ends in い and already contains "is". To negate it, replace the final い with く and add ない: 寒い → 寒くない. ではない goes after nouns, not after い-adjectives.', '寒い («è freddo») è un aggettivo in い: finisce in い e contiene già il «è». Per negarlo si sostituisce la い finale con く e si aggiunge ない: 寒い → 寒くない. ではない va dopo i nomi, non dopo gli aggettivi in い.'),
  ('fba6f22c-731b-51d4-a33f-9b4f83ba8de9', '否定の-ない', 'single-select', '{"sentence":{"kanji":"この映画はよくない","kana":"このえいがはよくない"},"answer":"よくない","distractors":["いくない","いいない","よいない"],"gap":{"kanji":"この映画は＿","kana":"このえいがは＿"},"prompt":{"en":"\"This film is not good.\" How do you say \"is not good\" (from いい)?","it":"«Questo film non è bello.» Come si dice «non è bello» (da いい)?"},"translation":{"en":"This film is not good.","it":"Questo film non è bello."},"glosses":[{"text":"よくない"},{"text":"いくない"},{"text":"いいない"},{"text":"よいない"}]}'::jsonb, '形容詞の否定「くない」', 'いい ("is good") is irregular: every change starts from its older form, よい. So "is not good" is よくない, and "was good" is よかった. いくない does not exist.', 'いい («è buono, è bello») è irregolare: ogni cambiamento parte dalla sua forma antica, よい. Quindi «non è bello» è よくない e «era bello» è よかった. いくない non esiste.'),
  ('b340d16c-bcce-5281-806c-2f88c74cfb10', '否定の-ない', 'assemble', '{"sentence":{"kanji":"昨日は雨が降らなかった","kana":"きのうはあめがふらなかった"},"answer":["昨日は","雨が","降らなかった"],"prompt":{"en":"Build: \"It did not rain yesterday.\"","it":"Componi: «Ieri non è piovuto.»"},"translation":{"en":"It did not rain yesterday.","it":"Ieri non è piovuto."},"glosses":[{"text":"昨日は","reading":"きのうは","meaning":{"en":"yesterday (は: the topic)","it":"ieri (は: il tema)"}},{"text":"雨が","reading":"あめが","meaning":{"en":"the rain (が: the subject)","it":"la pioggia (が: il soggetto)"}},{"text":"降らなかった","reading":"ふらなかった","meaning":{"en":"did not fall","it":"non è caduta"}}]}'::jsonb, '否定の「ない」', 'For "did not", first make the negative 降らない ("does not fall"), then turn the final い of ない into かった, as with any い-adjective: 降らなかった. The order is: when (昨日は), the subject (雨が), and the verb last.', 'Per il «non» al passato si fa prima il negativo 降らない («non cade»), poi la い finale di ない diventa かった, come in ogni aggettivo in い: 降らなかった. L''ordine è: quando (昨日は), il soggetto (雨が) e il verbo alla fine.'),
  ('a1216140-12ce-5d2a-935e-ab787b263c95', '否定の-ない', 'select-span', '{"sentence":{"kanji":"テレビを見なかった","kana":"テレビをみなかった"},"answer":{"start":2,"end":3},"prompt":{"en":"\"I didn''t watch TV.\" Which part means \"didn''t\" (\"not\" in the past)?","it":"«Non ho guardato la TV.» Quale parte è il «non» al passato?"},"translation":{"en":"I didn''t watch TV.","it":"Non ho guardato la TV."},"glosses":[{"text":"テレビを","meaning":{"en":"TV (を: the object)","it":"la TV (を: l''oggetto)"}},{"text":"見","reading":"み","meaning":{"en":"watch (the verb without る)","it":"guardare (il verbo senza る)"}},{"text":"なかった","meaning":{"en":"did not","it":"non (al passato)"}}]}'::jsonb, '否定の「ない」', 'Select なかった. 見る ("to watch") is an ichidan verb (a verb that simply drops る before an ending): 見る → 見 + ない = 見ない. The past of ない is なかった, so 見なかった = "didn''t watch".', 'Seleziona なかった. 見る («guardare») è un verbo ichidan (un verbo che perde solo る prima di una desinenza): 見る → 見 + ない = 見ない. Il passato di ない è なかった, quindi 見なかった = «non ho guardato».'),
  ('52bf43ea-e519-5318-be37-3953bf03d7be', '否定の-ない', 'single-select', '{"sentence":{"kanji":"私はたばこを吸いません","kana":"わたしはたばこをすいません"},"answer":"吸いません","distractors":["吸わません","吸うません","吸いまさない"],"gap":{"kanji":"私はたばこを＿","kana":"わたしはたばこを＿"},"prompt":{"en":"\"I don''t smoke.\" How do you say \"don''t smoke\" politely (from 吸う)?","it":"«Non fumo.» Come si dice «non fumo» in modo cortese (da 吸う)?"},"translation":{"en":"I don''t smoke.","it":"Non fumo."},"glosses":[{"text":"吸いません","reading":"すいません"},{"text":"吸わません","reading":"すわません"},{"text":"吸うません","reading":"すうません"},{"text":"吸いまさない","reading":"すいまさない"}]}'::jsonb, '丁寧な否定「ません」', 'In polite speech, "not" is ません, the negative of ます (the polite verb ending). Like ます, it goes after the i-stem, the verb with its last kana changed to the i-sound: 吸う → 吸い. So 吸います ("I smoke") becomes 吸いません ("I don''t smoke").', 'Nel registro cortese il «non» è ません, la forma negativa di ます (la desinenza cortese del verbo). Come ます, si attacca al radicale in i, cioè il verbo con l''ultimo kana cambiato nel suono i: 吸う → 吸い. Quindi 吸います («fumo») diventa 吸いません («non fumo»).'),
  ('0166bf28-bd05-5e80-b39f-30fd30d7b0be', '否定の-ない', 'assemble', '{"sentence":{"kanji":"これは私の傘ではない","kana":"これはわたしのかさではない"},"answer":["これは","私の","傘","ではない"],"prompt":{"en":"Build: \"This is not my umbrella.\"","it":"Componi: «Questo non è il mio ombrello.»"},"translation":{"en":"This is not my umbrella.","it":"Questo non è il mio ombrello."},"glosses":[{"text":"これは","meaning":{"en":"this (は: the topic)","it":"questo (は: il tema)"}},{"text":"私の","reading":"わたしの","meaning":{"en":"my","it":"il mio"}},{"text":"傘","reading":"かさ","meaning":{"en":"umbrella","it":"ombrello"}},{"text":"ではない","meaning":{"en":"is not","it":"non è"}}]}'::jsonb, '名詞文の否定「ではない」', 'After a noun, "is not" is ではない, the negative of だ (the word for "is" after nouns). It goes at the very end, right after the noun: 傘ではない = "is not an umbrella". The owner comes before the thing, joined by の: 私の傘 = "my umbrella".', 'Dopo un nome, «non è» si dice ではない, la forma negativa di だ (la parola che fa da «è» dopo i nomi). Va proprio alla fine, subito dopo il nome: 傘ではない = «non è un ombrello». Il possessore viene prima della cosa, unito da の: 私の傘 = «il mio ombrello».')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('890ece21-e470-5522-9007-238149cdf418', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"毎週手紙を書きます","kana":"まいしゅうてがみをかきます"},"answer":"書きます","distractors":["書くます","書かます","書こます"],"gap":{"kanji":"毎週手紙を＿","kana":"まいしゅうてがみを＿"},"prompt":{"en":"\"I write a letter every week.\" How do you say \"write\" politely (from 書く)?","it":"«Ogni settimana scrivo una lettera.» Come si dice «scrivo» in modo cortese (da 書く)?"},"translation":{"en":"I write a letter every week.","it":"Ogni settimana scrivo una lettera."},"glosses":[{"text":"書きます","reading":"かきます"},{"text":"書くます","reading":"かくます"},{"text":"書かます","reading":"かかます"},{"text":"書こます","reading":"かこます"}]}'::jsonb, '連用形につく「ます」「たい」', 'ます is an auxiliary (a piece added to a verb that changes its tone or meaning): it makes the verb polite. It attaches to the i-stem, the verb with its last kana changed to the i-sound: 書く → 書き + ます = 書きます. The meaning stays the same; only the tone becomes polite.', 'ます è un ausiliare (un pezzo che si aggiunge al verbo e ne cambia il tono o il significato): rende il verbo cortese. Si attacca al radicale in i, cioè il verbo con l''ultimo kana cambiato nel suono i: 書く → 書き + ます = 書きます. Il significato resta lo stesso, cambia solo il tono.'),
  ('9c01efa2-0480-512a-b7ec-ace89c604eb4', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"ゆっくり休みたい","kana":"ゆっくりやすみたい"},"answer":"休みたい","distractors":["休むたい","休またい","休みったい"],"gap":{"kanji":"ゆっくり＿","kana":"ゆっくり＿"},"prompt":{"en":"\"I want to rest properly.\" How do you say \"want to rest\" (from 休む)?","it":"«Voglio riposarmi con calma.» Come si dice «voglio riposarmi» (da 休む)?"},"translation":{"en":"I want to rest properly.","it":"Voglio riposarmi con calma."},"glosses":[{"text":"休みたい","reading":"やすみたい"},{"text":"休むたい","reading":"やすむたい"},{"text":"休またい","reading":"やすまたい"},{"text":"休みったい","reading":"やすみったい"}]}'::jsonb, '連用形につく「ます」「たい」', 'To say "want to", add たい to the i-stem (the verb with its last kana changed to the i-sound): 休む → 休み + たい = 休みたい. 休みたい ends in い and works like an い-adjective (a word ending in い that already contains "is"), so "don''t want to rest" is 休みたくない.', 'Per dire «voglio», si aggiunge たい al radicale in i (il verbo con l''ultimo kana cambiato nel suono i): 休む → 休み + たい = 休みたい. 休みたい finisce in い e funziona come un aggettivo in い (una parola in い che contiene già il «è»), quindi «non voglio riposarmi» è 休みたくない.'),
  ('cb90a02a-6d35-5b29-ae38-611a76e319d3', '動詞の語幹と助動詞', 'assemble', '{"sentence":{"kanji":"一緒に昼ごはんを食べましょう","kana":"いっしょにひるごはんをたべましょう"},"answer":["一緒に","昼ごはんを","食べましょう"],"prompt":{"en":"Build: \"Let''s have lunch together.\"","it":"Componi: «Pranziamo insieme.»"},"translation":{"en":"Let''s have lunch together.","it":"Pranziamo insieme."},"glosses":[{"text":"一緒に","reading":"いっしょに","meaning":{"en":"together","it":"insieme"}},{"text":"昼ごはんを","reading":"ひるごはんを","meaning":{"en":"lunch (を: the object)","it":"il pranzo (を: l''oggetto)"}},{"text":"食べましょう","reading":"たべましょう","meaning":{"en":"let''s eat","it":"mangiamo"}}]}'::jsonb, '連用形につく「ます」「たい」', 'ましょう means "let''s…" in polite speech; it comes from ます and attaches in the same place. 食べる is an ichidan verb (a verb that simply drops る), so the stem is 食べ and "let''s eat" is 食べましょう. The verb goes last, after "together" (一緒に) and the object (昼ごはんを).', 'ましょう significa «facciamo…» nel registro cortese; deriva da ます e si attacca nello stesso punto. 食べる è un verbo ichidan (un verbo che perde solo る), quindi il radicale è 食べ e «mangiamo» è 食べましょう. Il verbo va alla fine, dopo «insieme» (一緒に) e l''oggetto (昼ごはんを).'),
  ('5fd847ca-3b86-509a-94eb-615047363693', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"先生が生徒に本を読ませた","kana":"せんせいがせいとにほんをよませた"},"answer":"読ませた","distractors":["読みせた","読むさせた","読めさせた"],"gap":{"kanji":"先生が生徒に本を＿","kana":"せんせいがせいとにほんを＿"},"prompt":{"en":"\"The teacher had the pupils read a book.\" How do you say \"made (them) read\" (from 読む)?","it":"«L''insegnante ha fatto leggere un libro agli studenti.» Come si dice «ha fatto leggere» (da 読む)?"},"translation":{"en":"The teacher had the pupils read a book.","it":"L''insegnante ha fatto leggere un libro agli studenti."},"glosses":[{"text":"読ませた","reading":"よませた"},{"text":"読みせた","reading":"よみせた"},{"text":"読むさせた","reading":"よむさせた"},{"text":"読めさせた","reading":"よめさせた"}]}'::jsonb, '未然形につく「せる」「れる」', 'The causative means "make or let someone do". For verbs like 読む, change the last kana to the a-sound and add せる: 読む → 読ま + せる = 読ませる; in the past, 読ませた. The person who is made to act takes に: 生徒に = "the pupils".', 'Il causativo significa «far fare» o «lasciar fare». Per verbi come 読む si cambia l''ultimo kana nel suono a e si aggiunge せる: 読む → 読ま + せる = 読ませる; al passato, 読ませた. La persona a cui si fa fare l''azione prende に: 生徒に = «agli studenti».'),
  ('82a7d415-c9cc-5d00-8d43-37bb64d9afd1', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"母が子供に野菜を食べさせた","kana":"ははがこどもにやさいをたべさせた"},"answer":"食べさせた","distractors":["食べせた","食べらせた","食べませた"],"gap":{"kanji":"母が子供に野菜を＿","kana":"ははがこどもにやさいを＿"},"prompt":{"en":"\"The mother made the child eat vegetables.\" How do you say \"made (him) eat\" (from 食べる)?","it":"«La madre ha fatto mangiare le verdure al bambino.» Come si dice «ha fatto mangiare» (da 食べる)?"},"translation":{"en":"The mother made the child eat vegetables.","it":"La madre ha fatto mangiare le verdure al bambino."},"glosses":[{"text":"食べさせた","reading":"たべさせた"},{"text":"食べせた","reading":"たべせた"},{"text":"食べらせた","reading":"たべらせた"},{"text":"食べませた","reading":"たべませた"}]}'::jsonb, '未然形につく「せる」「れる」', '食べる is an ichidan verb (a verb that simply drops る before an ending). Ichidan verbs take the longer form of the causative ("make someone do"), させる: 食べる → 食べ + させる = 食べさせる; in the past, 食べさせた. The same holds for every auxiliary with two forms: the longer one goes on ichidan verbs.', '食べる è un verbo ichidan (un verbo che perde solo る prima di una desinenza). I verbi ichidan prendono la forma lunga del causativo («far fare»), させる: 食べる → 食べ + させる = 食べさせる; al passato, 食べさせた. Vale per ogni ausiliare con due forme: quella lunga va sui verbi ichidan.'),
  ('60424dec-be6d-5efb-a460-98282ec99bf0', '動詞の語幹と助動詞', 'select-span', '{"sentence":{"kanji":"財布を盗まれた","kana":"さいふをぬすまれた"},"answer":{"start":1,"end":2},"prompt":{"en":"\"My wallet was stolen.\" Which part makes 盗む (\"to steal\") passive and past?","it":"«Mi hanno rubato il portafoglio.» Quale parte rende 盗む («rubare») passivo e al passato?"},"translation":{"en":"My wallet was stolen.","it":"Mi hanno rubato il portafoglio."},"glosses":[{"text":"財布を盗","reading":"さいふをぬす","meaning":{"en":"the wallet (を: the object) + steal (first part)","it":"il portafoglio (を: l''oggetto) + rubare (prima parte)"}},{"text":"まれた","meaning":{"en":"was …-en (passive, past)","it":"è stato … (passivo, passato)"}}]}'::jsonb, '未然形につく「せる」「れる」', 'Select まれた. The passive ("something is done to someone") adds れる to the verb with its last kana changed to the a-sound: 盗む → 盗ま + れる; in the past, 盗まれた. The person it happened to ("me") is understood and not said.', 'Seleziona まれた. Il passivo («qualcosa viene fatto a qualcuno») aggiunge れる al verbo con l''ultimo kana cambiato nel suono a: 盗む → 盗ま + れる; al passato, 盗まれた. Chi l''ha subito («io») è sottinteso e non si dice.'),
  ('219d9482-5afc-5f6c-bddf-de8c75155efa', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"一緒に帰ろう","kana":"いっしょにかえろう"},"answer":"帰ろう","distractors":["帰りよう","帰るう","帰よう"],"gap":{"kanji":"一緒に＿","kana":"いっしょに＿"},"prompt":{"en":"\"Let''s go home together.\" How do you say \"let''s go home\" (from 帰る)?","it":"«Torniamo a casa insieme.» Come si dice «torniamo a casa» (da 帰る)?"},"translation":{"en":"Let''s go home together.","it":"Torniamo a casa insieme."},"glosses":[{"text":"帰ろう","reading":"かえろう"},{"text":"帰りよう","reading":"かえりよう"},{"text":"帰るう","reading":"かえるう"},{"text":"帰よう","reading":"かえよう"}]}'::jsonb, '意向形', 'The volitional form means "let''s…" (casual). For most verbs, change the last kana to the o-sound and add う: 帰る → 帰ろ + う = 帰ろう. 帰る ends in -eru but is not an ichidan verb (one that simply drops る), so it does not take よう.', 'La forma volitiva significa «facciamo…!» (informale). Per la maggior parte dei verbi si cambia l''ultimo kana nel suono o e si aggiunge う: 帰る → 帰ろ + う = 帰ろう. 帰る finisce in -eru ma non è un verbo ichidan (uno che perde solo る), quindi non prende よう.'),
  ('83685bf3-6246-59cf-b37c-fb267e5680a3', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"そろそろ始めよう","kana":"そろそろはじめよう"},"answer":"始めよう","distractors":["始めろう","始めおう","始まよう"],"gap":{"kanji":"そろそろ＿","kana":"そろそろ＿"},"prompt":{"en":"\"Let''s get started.\" How do you say \"let''s start\" (from 始める)?","it":"«Cominciamo.» Come si dice «cominciamo» (da 始める)?"},"translation":{"en":"Let''s get started.","it":"Cominciamo."},"glosses":[{"text":"始めよう","reading":"はじめよう"},{"text":"始めろう","reading":"はじめろう"},{"text":"始めおう","reading":"はじめおう"},{"text":"始まよう","reading":"はじまよう"}]}'::jsonb, '意向形', '始める ("to begin") is an ichidan verb (a verb that simply drops る before an ending). Its volitional form ("let''s…") drops る and adds よう: 始める → 始め + よう = 始めよう.', '始める («cominciare») è un verbo ichidan (un verbo che perde solo る prima di una desinenza). La sua forma volitiva («facciamo…!») toglie る e aggiunge よう: 始める → 始め + よう = 始めよう.'),
  ('3c0f7198-df17-5a0f-9d70-bc512d087a11', '動詞の語幹と助動詞', 'select-span', '{"sentence":{"kanji":"もっと寝たい","kana":"もっとねたい"},"answer":{"start":2,"end":3},"prompt":{"en":"\"I want to sleep more.\" Which part is the auxiliary, the piece added to the verb?","it":"«Voglio dormire ancora.» Quale parte è l''ausiliare, il pezzo aggiunto al verbo?"},"translation":{"en":"I want to sleep more.","it":"Voglio dormire ancora."},"glosses":[{"text":"もっと","meaning":{"en":"more","it":"di più, ancora"}},{"text":"寝","reading":"ね","meaning":{"en":"sleep (the verb without る)","it":"dormire (il verbo senza る)"}},{"text":"たい","meaning":{"en":"want to","it":"voglio"}}]}'::jsonb, '動詞の語幹と助動詞', 'Select たい. A Japanese verb is built from a stem (the part that stays fixed, here 寝 from 寝る) plus auxiliaries (pieces added after it that bring a meaning): たい adds "want to". 寝る simply drops る, so 寝 + たい = 寝たい.', 'Seleziona たい. Un verbo giapponese si costruisce con il radicale (la parte che resta fissa, qui 寝 da 寝る) più gli ausiliari (pezzi aggiunti dopo, che portano un significato): たい aggiunge «voglio». 寝る perde solo る, quindi 寝 + たい = 寝たい.'),
  ('7c505681-fe40-53ed-8543-71c94f8918be', '動詞の語幹と助動詞', 'assemble', '{"sentence":{"kanji":"週末に海で泳ごう","kana":"しゅうまつにうみでおよごう"},"answer":["週末に","海で","泳ごう"],"prompt":{"en":"Build: \"Let''s swim in the sea this weekend.\"","it":"Componi: «Questo fine settimana nuotiamo al mare.»"},"translation":{"en":"Let''s swim in the sea this weekend.","it":"Questo fine settimana nuotiamo al mare."},"glosses":[{"text":"週末に","reading":"しゅうまつに","meaning":{"en":"at the weekend","it":"nel fine settimana"}},{"text":"海で","reading":"うみで","meaning":{"en":"in the sea","it":"al mare"}},{"text":"泳ごう","reading":"およごう","meaning":{"en":"let''s swim","it":"nuotiamo"}}]}'::jsonb, '意向形', '泳ごう is the volitional form of 泳ぐ ("to swim"): it means "let''s swim". The last kana changes to the o-sound and う is added: 泳ぐ → 泳ご + う. The verb goes last: first when (週末に), then where (海で).', '泳ごう è la forma volitiva di 泳ぐ («nuotare»): significa «nuotiamo». L''ultimo kana passa al suono o e si aggiunge う: 泳ぐ → 泳ご + う. Il verbo va alla fine: prima quando (週末に), poi dove (海で).')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('65ce9fba-80c4-5be5-a3d4-bdcd2dc6b00f', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"図書館に本を借りに行く","kana":"としょかんにほんをかりにいく"},"answer":["図書館に","本を","借りに","行く"],"prompt":{"en":"Build: \"I go to the library to borrow a book.\"","it":"Componi: «Vado in biblioteca a prendere in prestito un libro.»"},"translation":{"en":"I go to the library to borrow a book.","it":"Vado in biblioteca a prendere in prestito un libro."},"glosses":[{"text":"図書館に","reading":"としょかんに","meaning":{"en":"to the library","it":"in biblioteca"}},{"text":"本を","reading":"ほんを","meaning":{"en":"a book (を: the object)","it":"un libro (を: l''oggetto)"}},{"text":"借りに","reading":"かりに","meaning":{"en":"to borrow (the purpose)","it":"a prendere in prestito (lo scopo)"}},{"text":"行く","reading":"いく","meaning":{"en":"go","it":"vado"}}]}'::jsonb, '目的を示す「に」', 'There are two に here: 図書館に says where you go, 借りに says why you go. For the purpose, take the i-stem of the verb (the form used before ます: 借ります → 借り) and add に. Then comes a verb of movement, like 行く ("to go").', 'Qui ci sono due に: 図書館に dice dove si va, 借りに dice perché si va. Per lo scopo si prende il radicale in i del verbo (la forma che si usa davanti a ます: 借ります → 借り) e si aggiunge に. Poi viene un verbo di movimento, come 行く («andare»).'),
  ('6fd6cdc9-b3a2-595a-a61b-b9601056c094', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"海に泳ぎに行った","kana":"うみにおよぎにいった"},"answer":"泳ぎに","distractors":["泳ぐに","泳いに","泳ぎで"],"gap":{"kanji":"海に＿行った","kana":"うみに＿いった"},"prompt":{"en":"\"I went to the sea to swim.\" How do you say \"to swim\" (the purpose)?","it":"«Sono andato al mare a nuotare.» Come si dice «a nuotare» (lo scopo)?"},"translation":{"en":"I went to the sea to swim.","it":"Sono andato al mare a nuotare."},"glosses":[{"text":"泳ぎに","reading":"およぎに"},{"text":"泳ぐに","reading":"およぐに"},{"text":"泳いに","reading":"およいに"},{"text":"泳ぎで","reading":"およぎで"}]}'::jsonb, '目的を示す「に」', 'To say why you go somewhere, take the i-stem of the verb (the form used before ます: 泳ぎます → 泳ぎ), add に, then a verb like 行く: 泳ぎに行った = "went to swim". The dictionary form 泳ぐ cannot take に here.', 'Per dire perché si va in un posto si prende il radicale in i del verbo (la forma che si usa davanti a ます: 泳ぎます → 泳ぎ), si aggiunge に e poi un verbo come 行く: 泳ぎに行った = «sono andato a nuotare». La forma base 泳ぐ qui non può prendere に.'),
  ('f8fe3190-e688-51fe-83d9-b05fe9c9fdc5', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"猫が庭にいる","kana":"ねこがにわにいる"},"answer":"に","distractors":["で","を"],"gap":{"kanji":"猫が庭＿いる","kana":"ねこがにわ＿いる"},"prompt":{"en":"\"The cat is in the garden.\" Which particle says where the cat is?","it":"«Il gatto è in giardino.» Quale particella dice dove si trova il gatto?"},"translation":{"en":"The cat is in the garden.","it":"Il gatto è in giardino."}}'::jsonb, '存在の場所を示す「に」', 'With いる ("to be there", for people and animals) and ある (the same, for things), the place is marked by に. で is for the place where you do an action ("eat at home"), and just being somewhere is not an action.', 'Con いる («esserci», per persone e animali) e ある (lo stesso, per le cose), il luogo si segna con に. で serve per il luogo dove si fa un''azione («mangiare a casa»), e il semplice trovarsi in un posto non è un''azione.'),
  ('ff2cd48a-e2f0-5e68-ae7d-5db0bcfc73f1', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"ここに傘がある","kana":"ここにかさがある"},"answer":{"start":0,"end":1},"prompt":{"en":"\"There is an umbrella here.\" Which part says where the umbrella is?","it":"«Qui c''è un ombrello.» Quale parte dice dove si trova l''ombrello?"},"translation":{"en":"There is an umbrella here.","it":"Qui c''è un ombrello."},"glosses":[{"text":"ここに","meaning":{"en":"here (に: the place)","it":"qui (に: il luogo)"}},{"text":"傘","reading":"かさ","meaning":{"en":"umbrella","it":"ombrello"}},{"text":"がある","meaning":{"en":"(が: the subject) + there is","it":"(が: il soggetto) + c''è"}}]}'::jsonb, '存在の場所を示す「に」', 'Select ここに ("here"). ある means "there is" (for things), and the place where the thing is takes に. The thing itself, 傘 ("umbrella"), takes が.', 'Seleziona ここに («qui»). ある significa «c''è» (per le cose), e il luogo in cui si trova la cosa prende に. La cosa stessa, 傘 («ombrello»), prende が.'),
  ('369af471-99a9-5cf0-a96d-b23acb38413b', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"兄は医者になった","kana":"あにはいしゃになった"},"answer":"に","distractors":["を","で"],"gap":{"kanji":"兄は医者＿なった","kana":"あにはいしゃ＿なった"},"prompt":{"en":"\"My older brother became a doctor.\" Which particle marks what he became?","it":"«Mio fratello maggiore è diventato medico.» Quale particella segna ciò che è diventato?"},"translation":{"en":"My older brother became a doctor.","it":"Mio fratello maggiore è diventato medico."}}'::jsonb, '変化の結果を示す「に」', 'なる means "to become". What someone or something becomes is marked by に: 医者になった = "became a doctor". This is how it works after a noun, such as 医者 ("doctor").', 'なる significa «diventare». Ciò che qualcuno o qualcosa diventa si segna con に: 医者になった = «è diventato medico». Funziona così dopo un nome, come 医者 («medico»).'),
  ('dd21cd3e-299e-5f96-9c2c-04ebcfb63da1', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"部屋が明るくなった","kana":"へやがあかるくなった"},"answer":"明るく","distractors":["明るいに","明るに","明るいく"],"gap":{"kanji":"部屋が＿なった","kana":"へやが＿なった"},"prompt":{"en":"\"The room became bright.\" Which form of 明るい (\"bright\") goes before なる (\"to become\")?","it":"«La stanza è diventata luminosa.» Quale forma di 明るい («luminoso») va davanti a なる («diventare»)?"},"translation":{"en":"The room became bright.","it":"La stanza è diventata luminosa."},"glosses":[{"text":"明るく","reading":"あかるく"},{"text":"明るに","reading":"あかるに"},{"text":"明るいに","reading":"あかるいに"},{"text":"明るいく","reading":"あかるいく"}]}'::jsonb, '変化の結果を示す「に」', '明るい is an い-adjective (a word that ends in い and already means "is bright"), and に goes after nouns, not after い-adjectives. Before なる, an い-adjective changes its final い into く: 明るくなった = "became bright".', '明るい è un aggettivo in い (una parola che finisce in い e significa già «è luminoso»), e に va dopo i nomi, non dopo gli aggettivi in い. Davanti a なる, un aggettivo in い cambia la い finale in く: 明るくなった = «è diventata luminosa».'),
  ('76e29e2e-d600-5905-8028-5b2f911e6d34', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"来月京都へ行く","kana":"らいげつきょうとへいく"},"answer":"へ","distractors":["が","の"],"gap":{"kanji":"来月京都＿行く","kana":"らいげつきょうと＿いく"},"prompt":{"en":"\"Next month I''m going to Kyoto.\" Which particle marks the direction?","it":"«Il mese prossimo vado a Kyoto.» Quale particella segna la direzione?"},"translation":{"en":"Next month I''m going to Kyoto.","it":"Il mese prossimo vado a Kyoto."}}'::jsonb, '方向を示す「へ」', 'As a particle, へ is read え, and it marks the direction you move in: 京都へ行く = "go to Kyoto". Here に would also be correct, because both can mark where you go. But へ cannot mark where something is: 庭へいる is wrong.', 'Quando è una particella, へ si legge え e indica la direzione in cui ci si muove: 京都へ行く = «andare a Kyoto». Qui andrebbe bene anche に, perché entrambe possono indicare dove si va. Ma へ non può indicare dove si trova qualcosa: 庭へいる è sbagliato.'),
  ('f335e931-eec1-5296-aecf-0a3b39c0a595', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"来年日本に行きます","kana":"らいねんにほんにいきます"},"answer":["来年","日本に","行きます"],"prompt":{"en":"Build: \"Next year I will go to Japan.\"","it":"Componi: «L''anno prossimo andrò in Giappone.»"},"translation":{"en":"Next year I will go to Japan.","it":"L''anno prossimo andrò in Giappone."},"glosses":[{"text":"来年","reading":"らいねん","meaning":{"en":"next year","it":"l''anno prossimo"}},{"text":"日本に","reading":"にほんに","meaning":{"en":"to Japan","it":"in Giappone"}},{"text":"行きます","reading":"いきます","meaning":{"en":"(will) go (polite)","it":"andrò (cortese)"}}]}'::jsonb, '目的地を示す「に」', 'With a verb of movement such as 行く ("to go"), the place you go to is marked by に: 日本に行きます = "go to Japan". A time word like 来年 ("next year") needs no particle and usually comes first. The verb goes last.', 'Con un verbo di movimento come 行く («andare»), il posto in cui si va si segna con に: 日本に行きます = «andare in Giappone». Una parola di tempo come 来年 («l''anno prossimo») non vuole particelle e di solito va all''inizio. Il verbo va alla fine.'),
  ('7f40ad29-ce7c-5b2b-bcc7-da693507d83b', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"うちに帰りたい","kana":"うちにかえりたい"},"answer":{"start":0,"end":1},"prompt":{"en":"\"I want to go home.\" Which part says where you want to go?","it":"«Voglio tornare a casa.» Quale parte dice dove si vuole andare?"},"translation":{"en":"I want to go home.","it":"Voglio tornare a casa."},"glosses":[{"text":"うちに","meaning":{"en":"(to) home","it":"a casa"}},{"text":"帰","reading":"かえ","meaning":{"en":"go back (first part of the verb)","it":"tornare (prima parte del verbo)"}},{"text":"りたい","meaning":{"en":"(end of the verb) + want to","it":"(fine del verbo) + voglio"}}]}'::jsonb, '目的地を示す「に」', 'Select うちに ("home"). 帰る means "to go back", and the place you go back to is the destination, marked by に. The same に marks where you go with 行く ("to go") and 来る ("to come").', 'Seleziona うちに («a casa»). 帰る significa «tornare», e il posto in cui si torna è la destinazione, segnata da に. Lo stesso に indica dove si va anche con 行く («andare») e 来る («venire»).'),
  ('c2ec2adf-2acc-5007-9d27-6e7c7b2bc603', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"ここへ来てください","kana":"ここへきてください"},"answer":{"start":0,"end":1},"prompt":{"en":"\"Please come here.\" Which part shows the direction of the movement?","it":"«Vieni qui, per favore.» Quale parte indica la direzione del movimento?"},"translation":{"en":"Please come here.","it":"Vieni qui, per favore."},"glosses":[{"text":"ここへ","meaning":{"en":"(towards) here","it":"(verso) qui"}},{"text":"来","reading":"き","meaning":{"en":"come (first part of the verb)","it":"venire (prima parte del verbo)"}},{"text":"てください","meaning":{"en":"please (do it)","it":"per favore (fallo)"}}]}'::jsonb, '方向を示す「へ」', 'Select ここへ ("here"). The particle へ, read え, marks the direction you move in; 来る ("to come") is a verb of movement, so it can take へ. に would also work: ここに来てください.', 'Seleziona ここへ («qui»). La particella へ, che si legge え, indica la direzione in cui ci si muove; 来る («venire») è un verbo di movimento, quindi può prendere へ. Andrebbe bene anche に: ここに来てください.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('d176c834-1d3d-5076-864b-72adb47f4948', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"図書館で勉強する","kana":"としょかんでべんきょうする"},"answer":"で","distractors":["に","を"],"gap":{"kanji":"図書館＿勉強する","kana":"としょかん＿べんきょうする"},"prompt":{"en":"\"I study at the library.\" Which particle says where the action happens?","it":"«Studio in biblioteca.» Quale particella dice dove avviene l''azione?"},"translation":{"en":"I study at the library.","it":"Studio in biblioteca."}}'::jsonb, '動作の場所を示す「で」', 'で is a particle (a small word after a noun that shows its role) that marks where an action happens. Studying is an action, so the library takes で. に would only say where you go or where something is.', 'で è una particella (una piccola parola dopo un nome che ne indica il ruolo) che segna dove avviene un''azione. Studiare è un''azione, quindi la biblioteca prende で. に direbbe solo dove si va o dove si trova qualcosa.'),
  ('e12190eb-47b7-5eab-b513-73b09b4713aa', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"姉は台所にいる","kana":"あねはだいどころにいる"},"answer":"に","distractors":["で","を"],"gap":{"kanji":"姉は台所＿いる","kana":"あねはだいどころ＿いる"},"prompt":{"en":"\"My older sister is in the kitchen.\" Which particle says where she is?","it":"«Mia sorella maggiore è in cucina.» Quale particella dice dove si trova?"},"translation":{"en":"My older sister is in the kitchen.","it":"Mia sorella maggiore è in cucina."}}'::jsonb, '動作の場所を示す「で」', 'いる means "to be (somewhere)": nobody is doing anything, it only says where she is. For the place where someone simply is, Japanese uses に. Compare 台所で料理する, "cooks in the kitchen": that is an action, so で.', 'いる significa «trovarsi»: nessuno sta facendo qualcosa, dice solo dove si trova la sorella. Per il luogo dove qualcuno semplicemente sta, il giapponese usa に. Confronta 台所で料理する, «cucina in cucina»: lì c''è un''azione, quindi で.'),
  ('52e10f75-c252-59df-b6a8-d4362bae79a6', '動作の場所を示す-で', 'select-span', '{"sentence":{"kanji":"ペンで名前を書いた","kana":"ペンでなまえをかいた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says what was used to write?","it":"Quale parte dice con che cosa si è scritto?"},"translation":{"en":"I wrote my name with a pen.","it":"Ho scritto il mio nome con una penna."},"glosses":[{"text":"ペンで","meaning":{"en":"with a pen","it":"con una penna"}},{"text":"名前を書","reading":"なまえをか","meaning":{"en":"name (what is written) + first part of 書く, \"write\"","it":"nome (ciò che si scrive) + inizio di 書く, «scrivere»"}},{"text":"いた","meaning":{"en":"end of 書いた, \"wrote\"","it":"fine di 書いた, «ho scritto»"}}]}'::jsonb, '手段を示す「で」', 'Select ペンで, "with a pen". Besides the place of an action, で also marks the tool you use to do it. The name is what gets written, so it takes を, the particle for the object (the thing the action is done to).', 'Seleziona ペンで, «con una penna». Oltre al luogo di un''azione, で segna anche lo strumento con cui la fai. Il nome è ciò che viene scritto, quindi prende を, la particella dell''oggetto (la cosa su cui cade l''azione).'),
  ('4c9bdd6a-99e8-52b1-9dd1-e1df78cda4d4', '動作の場所を示す-で', 'assemble', '{"sentence":{"kanji":"自転車で学校に通う","kana":"じてんしゃでがっこうにかよう"},"answer":["自転車で","学校に","通う"],"prompt":{"en":"Build: \"I go to school by bicycle.\"","it":"Componi: «Vado a scuola in bicicletta.»"},"translation":{"en":"I go to school by bicycle.","it":"Vado a scuola in bicicletta."},"glosses":[{"text":"自転車で","reading":"じてんしゃで","meaning":{"en":"by bicycle","it":"in bicicletta"}},{"text":"学校に","reading":"がっこうに","meaning":{"en":"to school","it":"a scuola"}},{"text":"通う","reading":"かよう","meaning":{"en":"go regularly","it":"andare abitualmente"}}]}'::jsonb, '手段を示す「で」', 'A vehicle is a means, just like a pen or a language, so it takes the particle で: 自転車で, "by bicycle". The place you go to takes に: 学校に, "to school".', 'Un veicolo è un mezzo, proprio come una penna o una lingua, quindi prende la particella で: 自転車で, «in bicicletta». Il luogo dove vai prende に: 学校に, «a scuola».'),
  ('0bfa5305-e678-52b2-be6c-c6a0e5b761d8', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"英語で手紙を書いた","kana":"えいごでてがみをかいた"},"answer":"で","distractors":["を","が"],"gap":{"kanji":"英語＿手紙を書いた","kana":"えいご＿てがみをかいた"},"prompt":{"en":"\"I wrote a letter in English.\" Which particle goes after the language used?","it":"«Ho scritto una lettera in inglese.» Quale particella va dopo la lingua usata?"},"translation":{"en":"I wrote a letter in English.","it":"Ho scritto una lettera in inglese."}}'::jsonb, '手段を示す「で」', 'The language you speak or write in is a means too, so it takes で: 英語で, "in English". を is already used for the letter, the thing that gets written.', 'Anche la lingua in cui parli o scrivi è un mezzo, quindi prende で: 英語で, «in inglese». を è già usato per la lettera, la cosa che viene scritta.'),
  ('8369e4be-0eaf-5345-8615-b6b8d8a98d93', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"パンと牛乳を買った","kana":"パンとぎゅうにゅうをかった"},"answer":"と","distractors":["を","へ"],"gap":{"kanji":"パン＿牛乳を買った","kana":"パン＿ぎゅうにゅうをかった"},"prompt":{"en":"\"I bought bread and milk.\" Which particle joins the two nouns?","it":"«Ho comprato pane e latte.» Quale particella unisce i due nomi?"},"translation":{"en":"I bought bread and milk.","it":"Ho comprato pane e latte."}}'::jsonb, '名詞をつなぐ「と」', 'と between two nouns means "and": パンと牛乳, "bread and milk". It only makes a list. The を after the last noun makes the whole list the object of 買った (the things bought).', 'と fra due nomi significa «e»: パンと牛乳, «pane e latte». Serve solo a fare un elenco. Il を dopo l''ultimo nome rende tutto l''elenco l''oggetto di 買った (le cose comprate).'),
  ('dd3ffd65-32ba-5b83-b664-6ed29a402cdb', '動作の場所を示す-で', 'assemble', '{"sentence":{"kanji":"兄と弟が川で泳いでいる","kana":"あにとおとうとがかわでおよいでいる"},"answer":["兄と","弟が","川で","泳いでいる"],"prompt":{"en":"Build: \"My older and younger brothers are swimming in the river.\"","it":"Componi: «Il fratello maggiore e il minore stanno nuotando nel fiume.»"},"translation":{"en":"My older and younger brothers are swimming in the river.","it":"Il fratello maggiore e il minore stanno nuotando nel fiume."},"glosses":[{"text":"兄と","reading":"あにと","meaning":{"en":"older brother and","it":"fratello maggiore e"}},{"text":"弟が","reading":"おとうとが","meaning":{"en":"younger brother + が (who does it)","it":"fratello minore + が (chi lo fa)"}},{"text":"川で","reading":"かわで","meaning":{"en":"in the river","it":"nel fiume"}},{"text":"泳いでいる","reading":"およいでいる","meaning":{"en":"are swimming","it":"stanno nuotando"}}]}'::jsonb, '名詞をつなぐ「と」', '兄と弟 means "older brother and younger brother": と joins them into one group. が after the group marks both as the subject (who does the action). 川で says where they swim: it is an action, so で.', '兄と弟 significa «fratello maggiore e fratello minore»: と li unisce in un solo gruppo. が dopo il gruppo li segna entrambi come soggetto (chi fa l''azione). 川で dice dove nuotano: è un''azione, quindi で.'),
  ('645e1b4a-08c3-5488-9072-ca1e40bda4aa', '動作の場所を示す-で', 'select-span', '{"sentence":{"kanji":"レストランで晩ご飯を食べた","kana":"レストランでばんごはんをたべた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says where the action happened?","it":"Quale parte dice dove è avvenuta l''azione?"},"translation":{"en":"I ate dinner at a restaurant.","it":"Ho cenato al ristorante."},"glosses":[{"text":"レストランで","meaning":{"en":"at a restaurant","it":"al ristorante"}},{"text":"晩ご飯を食","reading":"ばんごはんをた","meaning":{"en":"dinner (what is eaten) + first part of 食べる, \"eat\"","it":"cena (ciò che si mangia) + inizio di 食べる, «mangiare»"}},{"text":"べた","meaning":{"en":"end of 食べた, \"ate\"","it":"fine di 食べた, «ho mangiato»"}}]}'::jsonb, '動作の場所を示す「で」', 'Select レストランで, "at a restaurant". Eating is an action, and the place where an action happens takes the particle で (a small word that marks where it happens). Without an action, for example with いる, "to be there", the place would take に.', 'Seleziona レストランで, «al ristorante». Mangiare è un''azione, e il luogo dove avviene un''azione prende la particella で (una piccola parola che segna dove avviene). Senza un''azione, per esempio con いる, «trovarsi», il luogo prenderebbe に.'),
  ('cae1f7df-e77a-5547-ab1f-82628cce9bba', '動作の場所を示す-で', 'select-span', '{"sentence":{"kanji":"バスで学校に行く","kana":"バスでがっこうにいく"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says how I get there?","it":"Quale parte dice con che mezzo ci vado?"},"translation":{"en":"I go to school by bus.","it":"Vado a scuola in autobus."},"glosses":[{"text":"バスで","meaning":{"en":"by bus","it":"in autobus"}},{"text":"学校に行","reading":"がっこうにい","meaning":{"en":"to school + first part of 行く, \"go\"","it":"a scuola + inizio di 行く, «andare»"}},{"text":"く","meaning":{"en":"end of 行く","it":"fine di 行く"}}]}'::jsonb, '手段を示す「で」', 'Select バスで, "by bus". The particle で also marks the means you use: a tool, a language or, as here, a vehicle. The place you go to takes に: 学校に.', 'Seleziona バスで, «in autobus». La particella で segna anche il mezzo che usi: uno strumento, una lingua o, come qui, un veicolo. Il luogo dove vai prende に: 学校に.'),
  ('55f9a8e1-380e-5eb0-9665-a1d228d2631a', '動作の場所を示す-で', 'assemble', '{"sentence":{"kanji":"机の上に本とノートがある","kana":"つくえのうえにほんとノートがある"},"answer":["机の上に","本と","ノートが","ある"],"prompt":{"en":"Build: \"There are a book and a notebook on the desk.\"","it":"Componi: «Sulla scrivania ci sono un libro e un quaderno.»"},"translation":{"en":"There are a book and a notebook on the desk.","it":"Sulla scrivania ci sono un libro e un quaderno."},"glosses":[{"text":"机の上に","reading":"つくえのうえに","meaning":{"en":"on the desk","it":"sulla scrivania"}},{"text":"本と","reading":"ほんと","meaning":{"en":"a book and","it":"un libro e"}},{"text":"ノートが","meaning":{"en":"notebook + が (what is there)","it":"quaderno + が (ciò che c''è)"}},{"text":"ある","meaning":{"en":"there is, there are (for things)","it":"c''è, ci sono (per le cose)"}}]}'::jsonb, '名詞をつなぐ「と」', '本とノート means "a book and a notebook": と joins two nouns into a list. が after the list marks what is there, and ある says that things are in a place. The place takes に, because ある is not an action.', '本とノート significa «un libro e un quaderno»: と unisce due nomi in un elenco. が dopo l''elenco segna ciò che c''è, e ある dice che delle cose si trovano in un luogo. Il luogo prende に, perché ある non è un''azione.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('53fc7beb-c295-5291-89ec-7310f54c0e85', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"私は犬が好きだ","kana":"わたしはいぬがすきだ"},"answer":"が","distractors":["を","で"],"gap":{"kanji":"私は犬＿好きだ","kana":"わたしはいぬ＿すきだ"},"prompt":{"en":"\"I like dogs.\" Which particle goes after what is liked?","it":"«Mi piacciono i cani.» Quale particella va dopo ciò che piace?"},"translation":{"en":"I like dogs.","it":"Mi piacciono i cani."}}'::jsonb, '感情・理解の述語と「が」', '好き ("liked") is not a verb but a な-adjective: a describing word that ends the sentence with だ, "is". を is only for the object of a verb (the thing an action is done to), so what is liked takes が: 犬が好きだ. 私は is the topic: who the sentence is about.', '好き («che piace») non è un verbo ma un aggettivo in な: una parola che descrive e chiude la frase con だ, cioè «è». を serve solo per l''oggetto di un verbo (la cosa su cui cade l''azione), quindi ciò che piace prende が: 犬が好きだ. 私は è il tema: la persona di cui parla la frase.'),
  ('e3af00c5-e946-563c-bbf1-d525bb7067c2', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"弟は漢字が分かる","kana":"おとうとはかんじがわかる"},"answer":"が","distractors":["を","で"],"gap":{"kanji":"弟は漢字＿分かる","kana":"おとうとはかんじ＿わかる"},"prompt":{"en":"\"My younger brother understands kanji.\" Which particle goes after what is understood?","it":"«Mio fratello minore capisce i kanji.» Quale particella va dopo ciò che si capisce?"},"translation":{"en":"My younger brother understands kanji.","it":"Mio fratello minore capisce i kanji."}}'::jsonb, '感情・理解の述語と「が」', '分かる means "to be clear, understandable": it describes a state, not an action done to something. So what is understood takes が, never を: 漢字が分かる. 弟は is the topic: who the sentence is about.', '分かる significa «essere chiaro, comprensibile»: descrive uno stato, non un''azione fatta su qualcosa. Per questo ciò che si capisce prende が, mai を: 漢字が分かる. 弟は è il tema: la persona di cui parla la frase.'),
  ('f8a17f20-6a3c-5b1f-abde-422365eb833a', '感情-理解の述語と-が', 'assemble', '{"sentence":{"kanji":"新しい自転車がほしい","kana":"あたらしいじてんしゃがほしい"},"answer":["新しい","自転車が","ほしい"],"prompt":{"en":"Build: \"I want a new bicycle.\"","it":"Componi: «Voglio una bicicletta nuova.»"},"translation":{"en":"I want a new bicycle.","it":"Voglio una bicicletta nuova."},"glosses":[{"text":"新しい","reading":"あたらしい","meaning":{"en":"new","it":"nuova"}},{"text":"自転車が","reading":"じてんしゃが","meaning":{"en":"bicycle + が (what is wanted)","it":"bicicletta + が (ciò che si vuole)"}},{"text":"ほしい","meaning":{"en":"wanted (I want)","it":"desiderato (voglio)"}}]}'::jsonb, '欲求の「ほしい」と「たい」', 'ほしい ("wanted") ends in い: it is an い-adjective (a describing word ending in い), not a verb. So the thing you want takes が: 自転車がほしい. If no one else is named, the wish is the speaker''s: "I want".', 'ほしい («desiderato») finisce in い: è un aggettivo in い (una parola che descrive e finisce in い), non un verbo. Per questo la cosa che vuoi prende が: 自転車がほしい. Se non si nomina nessun altro, il desiderio è di chi parla: «voglio».'),
  ('cfc027a4-598d-522e-aeff-53f35b8f2e4f', '感情-理解の述語と-が', 'select-span', '{"sentence":{"kanji":"ラーメンが食べたい","kana":"ラーメンがたべたい"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the thing that is wanted?","it":"Quale parte è la cosa desiderata?"},"translation":{"en":"I want to eat ramen.","it":"Voglio mangiare il ramen."},"glosses":[{"text":"ラーメンが","meaning":{"en":"ramen + が (what is wanted)","it":"ramen + が (ciò che si vuole)"}},{"text":"食","reading":"た","meaning":{"en":"eat (kanji of 食べる)","it":"mangiare (kanji di 食べる)"}},{"text":"べたい","meaning":{"en":"rest of 食べ + たい, \"want to\"","it":"resto di 食べ + たい, «voler fare»"}}]}'::jsonb, '欲求の「ほしい」と「たい」', 'Select ラーメンが, the thing you want. 食べたい is 食べ (from 食べる, "eat") + たい, "want to"; たい ends in い and works like an adjective, so what you want can take が. ラーメンを食べたい is also correct; が is the more traditional choice.', 'Seleziona ラーメンが, ciò che si vuole. 食べたい è 食べ (da 食べる, «mangiare») + たい, «voler fare»; たい finisce in い e funziona come un aggettivo, quindi ciò che vuoi può prendere が. Anche ラーメンを食べたい è corretto; が è la scelta più tradizionale.'),
  ('9c045dfa-041f-5013-ac0a-02f0d02c79ed', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"妹が新しいゲームをほしがっている","kana":"いもうとがあたらしいゲームをほしがっている"},"answer":"ほしがっている","distractors":["ほしい","ほしいだ","ほしくている"],"gap":{"kanji":"妹が新しいゲームを＿","kana":"いもうとがあたらしいゲームを＿"},"prompt":{"en":"\"My younger sister wants a new game.\" How do you say that someone else wants something?","it":"«Mia sorella minore vuole un gioco nuovo.» Come si dice che un''altra persona vuole qualcosa?"},"translation":{"en":"My younger sister wants a new game.","it":"Mia sorella minore vuole un gioco nuovo."}}'::jsonb, '他人の感情を示す「がる」', 'ほしい and たい express only the speaker''s own feelings: you can''t know from the inside what another person feels. For someone else, drop the final い and add がる, "to show signs of": ほしい → ほしがる, here as ほしがっている, "is wanting". ほしがる is a verb, so the thing wanted takes を.', 'ほしい e たい esprimono solo i sentimenti di chi parla: quello che prova un altro non lo puoi sapere da dentro. Per un''altra persona si toglie la い finale e si aggiunge がる, «mostrare segni di»: ほしい → ほしがる, qui ほしがっている, «sta desiderando». ほしがる è un verbo, quindi la cosa voluta prende を.'),
  ('433e230a-0f7d-5b8b-9da7-1f844e6d758c', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"子供が外で遊びたがっている","kana":"こどもがそとであそびたがっている"},"answer":"遊びたがっている","distractors":["遊びたい","遊びたいだ","遊ぶたがっている"],"gap":{"kanji":"子供が外で＿","kana":"こどもがそとで＿"},"prompt":{"en":"\"The child wants to play outside.\" How do you describe the child''s wish?","it":"«Il bambino vuole giocare fuori.» Come si descrive il desiderio del bambino?"},"translation":{"en":"The child wants to play outside.","it":"Il bambino vuole giocare fuori."},"glosses":[{"text":"遊びたがっている","reading":"あそびたがっている"},{"text":"遊びたい","reading":"あそびたい"},{"text":"遊びたいだ","reading":"あそびたいだ"},{"text":"遊ぶたがっている","reading":"あそぶたがっている"}]}'::jsonb, '他人の感情を示す「がる」', '遊びたい ("I want to play") can only describe the speaker''s wish. For the child, たい drops its い and takes がる: 遊びたがる, "shows that they want to play". Here it is in the ている form, which describes what is going on now: 遊びたがっている.', '遊びたい («voglio giocare») descrive solo il desiderio di chi parla. Per il bambino, たい perde la い e prende がる: 遊びたがる, «mostra di voler giocare». Qui è nella forma in ている, che descrive ciò che succede adesso: 遊びたがっている.'),
  ('9d13b41f-8fa9-52c8-af21-43348680ed89', '感情-理解の述語と-が', 'select-span', '{"sentence":{"kanji":"スポーツが好きです","kana":"スポーツがすきです"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the thing that is liked?","it":"Quale parte è ciò che piace?"},"translation":{"en":"I like sports.","it":"Mi piace lo sport."},"glosses":[{"text":"スポーツが","meaning":{"en":"sports + が (what is liked)","it":"sport + が (ciò che piace)"}},{"text":"好","reading":"す","meaning":{"en":"liked (kanji of 好き)","it":"che piace (kanji di 好き)"}},{"text":"きです","meaning":{"en":"end of 好き + です, polite \"is\"","it":"fine di 好き + です, «è» cortese"}}]}'::jsonb, '感情・理解の述語と「が」', 'Select スポーツが. 好き ("liked") is a な-adjective, a describing word, not a verb, so it has no object with を. What is liked takes が: スポーツが好きです, where です is a polite "is".', 'Seleziona スポーツが. 好き («che piace») è un aggettivo in な, una parola che descrive, non un verbo, quindi non ha un oggetto con を. Ciò che piace prende が: スポーツが好きです, dove です è «è» in forma cortese.'),
  ('49892eb0-946c-5fb5-8514-e3459fc00663', '感情-理解の述語と-が', 'select-span', '{"sentence":{"kanji":"ねこが外に出たがっている","kana":"ねこがそとにでたがっている"},"answer":{"start":2,"end":3},"prompt":{"en":"Which part shows that the wish belongs to someone else, not the speaker?","it":"Quale parte mostra che il desiderio è di qualcun altro, non di chi parla?"},"translation":{"en":"The cat wants to go outside.","it":"Il gatto vuole uscire."},"glosses":[{"text":"ねこが","meaning":{"en":"cat + が (who wants it)","it":"gatto + が (chi lo vuole)"}},{"text":"外に出","reading":"そとにで","meaning":{"en":"outside + first part of 出る, \"go out\"","it":"fuori + inizio di 出る, «uscire»"}},{"text":"たがっている","meaning":{"en":"wants to (as seen from outside)","it":"vuole (visto da fuori)"}}]}'::jsonb, '他人の感情を示す「がる」', 'Select たがっている. 出たい would mean "I want to go out", the speaker''s own wish. For anyone else, even a cat, たい becomes たがる, "shows that it wants to", here as たがっている, "is showing it now".', 'Seleziona たがっている. 出たい significherebbe «voglio uscire», il desiderio di chi parla. Per chiunque altro, anche un gatto, たい diventa たがる, «mostra di voler fare», qui たがっている, «lo sta mostrando adesso».'),
  ('839acd0d-8db3-5e15-8a53-1ad6ed96d9ef', '感情-理解の述語と-が', 'assemble', '{"sentence":{"kanji":"私は日本語が少し分かる","kana":"わたしはにほんごがすこしわかる"},"answer":["私は","日本語が","少し","分かる"],"prompt":{"en":"Build: \"I understand a little Japanese.\"","it":"Componi: «Capisco un po'' di giapponese.»"},"translation":{"en":"I understand a little Japanese.","it":"Capisco un po'' di giapponese."},"glosses":[{"text":"私は","reading":"わたしは","meaning":{"en":"I (topic)","it":"io (tema)"}},{"text":"日本語が","reading":"にほんごが","meaning":{"en":"Japanese + が (what is understood)","it":"giapponese + が (ciò che si capisce)"}},{"text":"少し","reading":"すこし","meaning":{"en":"a little","it":"un po''"}},{"text":"分かる","reading":"わかる","meaning":{"en":"understand","it":"capire"}}]}'::jsonb, '感情・理解の述語と「が」', '分かる ("understand") describes a state, so what is understood takes が, not を: 日本語が分かる. 私は is the topic, the person the sentence is about. 少し, "a little", goes right before the verb it describes.', '分かる («capire») descrive uno stato, quindi ciò che si capisce prende が, non を: 日本語が分かる. 私は è il tema, la persona di cui parla la frase. 少し, «un po''», va subito prima del verbo che descrive.'),
  ('54bbee0f-608f-5d7b-b294-0fe2522f7c29', '感情-理解の述語と-が', 'assemble', '{"sentence":{"kanji":"夏休みに日本へ行きたい","kana":"なつやすみににほんへいきたい"},"answer":["夏休みに","日本へ","行きたい"],"prompt":{"en":"Build: \"I want to go to Japan in the summer holidays.\"","it":"Componi: «Nelle vacanze estive voglio andare in Giappone.»"},"translation":{"en":"I want to go to Japan in the summer holidays.","it":"Nelle vacanze estive voglio andare in Giappone."},"glosses":[{"text":"夏休みに","reading":"なつやすみに","meaning":{"en":"in the summer holidays","it":"nelle vacanze estive"}},{"text":"日本へ","reading":"にほんへ","meaning":{"en":"to Japan","it":"in Giappone"}},{"text":"行きたい","reading":"いきたい","meaning":{"en":"want to go","it":"voler andare"}}]}'::jsonb, '欲求の「ほしい」と「たい」', 'To say "want to do", take the verb''s i-stem (the part before ます: 行きます → 行き) and add たい: 行きたい, "want to go". In a statement, たい is always the speaker''s own wish. The place you head to takes へ, "towards".', 'Per dire «voglio fare», si prende il radicale in i del verbo (la parte davanti a ます: 行きます → 行き) e si aggiunge たい: 行きたい, «voglio andare». In un''affermazione, たい è sempre il desiderio di chi parla. Il luogo verso cui vai prende へ, «verso».')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('b1fa153e-1704-5115-b2ea-fcb8cb5e0483', '可能形', 'single-select', '{"sentence":{"kanji":"この川で泳げる","kana":"このかわでおよげる"},"answer":"泳げる","distractors":["泳ぎる","泳ぐれる","泳げられる"],"gap":{"kanji":"この川で＿","kana":"このかわで＿"},"prompt":{"en":"\"You can swim in this river.\" What is the potential form of 泳ぐ?","it":"«In questo fiume si può nuotare.» Qual è la forma potenziale di 泳ぐ?"},"translation":{"en":"You can swim in this river.","it":"In questo fiume si può nuotare."},"glosses":[{"text":"泳げる","reading":"およげる"},{"text":"泳げられる","reading":"およげられる"},{"text":"泳ぐれる","reading":"およぐれる"},{"text":"泳ぎる","reading":"およぎる"}]}'::jsonb, '可能形', 'The potential form is the verb form that means "can do": 泳げる = "can swim". 泳ぐ is a godan verb (a verb whose last kana changes, like 書く, 読む): the final u-sound becomes an e-sound, ぐ → げ, and る is added. The new verb 泳げる then works like 食べる.', 'La forma potenziale è la forma del verbo che dice «posso fare»: 泳げる = «si può nuotare». 泳ぐ è un verbo godan (un verbo il cui ultimo kana cambia, come 書く, 読む): il suono finale in u diventa in e, ぐ → げ, e si aggiunge る. Il nuovo verbo 泳げる poi si comporta come 食べる.'),
  ('e2e3e4f9-6c89-55ea-a10b-e438b2cbfa7c', '可能形', 'single-select', '{"sentence":{"kanji":"この魚は生で食べられる","kana":"このさかなはなまでたべられる"},"answer":"食べられる","distractors":["食べえる","食べらる","食べされる"],"gap":{"kanji":"この魚は生で＿","kana":"このさかなはなまで＿"},"prompt":{"en":"\"This fish can be eaten raw.\" What is the potential form of 食べる?","it":"«Questo pesce si può mangiare crudo.» Qual è la forma potenziale di 食べる?"},"translation":{"en":"This fish can be eaten raw.","it":"Questo pesce si può mangiare crudo."},"glosses":[{"text":"食べられる","reading":"たべられる"},{"text":"食べされる","reading":"たべされる"},{"text":"食べらる","reading":"たべらる"},{"text":"食べえる","reading":"たべえる"}]}'::jsonb, '可能形', 'The potential form means "can do". 食べる is an ichidan verb (a verb ending in -eru or -iru that simply drops る, like 見る, 寝る): remove る and add られる, 食べられる, "can be eaten". In casual speech you also hear 食べれる, but 食べられる is the standard form.', 'La forma potenziale dice «posso fare». 食べる è un verbo ichidan (un verbo in -eru o -iru che perde semplicemente る, come 見る, 寝る): si toglie る e si aggiunge られる, 食べられる, «si può mangiare». Nel parlato informale si sente anche 食べれる, ma la forma standard è 食べられる.'),
  ('86dd7435-ccdf-554c-951f-5a0c3815cda7', '可能形', 'single-select', '{"sentence":{"kanji":"兄は中国語ができる","kana":"あにはちゅうごくごができる"},"answer":"できる","distractors":["するれる","しれる","すられる"],"gap":{"kanji":"兄は中国語が＿","kana":"あにはちゅうごくごが＿"},"prompt":{"en":"\"My older brother can speak Chinese.\" What is the potential form of する (\"do\")?","it":"«Mio fratello maggiore sa il cinese.» Qual è la forma potenziale di する («fare»)?"},"translation":{"en":"My older brother can speak Chinese.","it":"Mio fratello maggiore sa il cinese."}}'::jsonb, '不規則動詞の可能形', 'する ("to do") is irregular: its potential form ("can do") is a different verb, できる. What someone can do takes が: 中国語ができる, "Chinese is something he can do", so "he can speak Chinese".', 'する («fare») è irregolare: la sua forma potenziale («poter fare») è un verbo diverso, できる. Ciò che si sa o si può fare prende が: 中国語ができる, «il cinese è una cosa che sa fare», cioè «sa parlare cinese».'),
  ('84c9b0a0-3ca9-517a-801b-c339fed2146e', '可能形', 'select-span', '{"sentence":{"kanji":"ひらがなが読める","kana":"ひらがながよめる"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the thing that can be read?","it":"Quale parte è ciò che si riesce a leggere?"},"translation":{"en":"I can read hiragana.","it":"So leggere lo hiragana."},"glosses":[{"text":"ひらがなが","meaning":{"en":"hiragana + が (what can be read)","it":"hiragana + が (ciò che si sa leggere)"}},{"text":"読","reading":"よ","meaning":{"en":"read (kanji of 読む)","it":"leggere (kanji di 読む)"}},{"text":"める","meaning":{"en":"end of 読める, \"can read\"","it":"fine di 読める, «saper leggere»"}}]}'::jsonb, '可能形と「が」', 'Select ひらがなが. 読める ("can read") is the potential form of 読む: it describes an ability, a state, more than an action. So the thing you can read usually takes が instead of を.', 'Seleziona ひらがなが. 読める («saper leggere») è la forma potenziale di 読む: descrive una capacità, uno stato, più che un''azione. Per questo ciò che si sa leggere di solito prende が invece di を.'),
  ('b3a6d49e-13cf-516e-a87e-a19b5e30bcfd', '可能形', 'single-select', '{"sentence":{"kanji":"昨日はよく眠れなかった","kana":"きのうはよくねむれなかった"},"answer":"眠れなかった","distractors":["眠りれなかった","眠るなかった","眠れないかった"],"gap":{"kanji":"昨日はよく＿","kana":"きのうはよく＿"},"prompt":{"en":"\"I couldn''t sleep well yesterday.\" How do you say \"couldn''t sleep\"?","it":"«Ieri non sono riuscito a dormire bene.» Come si dice «non sono riuscito a dormire»?"},"translation":{"en":"I couldn''t sleep well yesterday.","it":"Ieri non sono riuscito a dormire bene."},"glosses":[{"text":"眠れなかった","reading":"ねむれなかった"},{"text":"眠れないかった","reading":"ねむれないかった"},{"text":"眠りれなかった","reading":"ねむりれなかった"},{"text":"眠るなかった","reading":"ねむるなかった"}]}'::jsonb, '可能形', '眠れる ("can sleep") is the potential form of 眠る. Every potential form works like 食べる: drop る and add ない for "not", then ない becomes なかった for the past. 眠れる → 眠れない → 眠れなかった, "couldn''t sleep".', '眠れる («riuscire a dormire») è la forma potenziale di 眠る. Ogni forma potenziale si comporta come 食べる: si toglie る e si aggiunge ない per il «non», poi ない diventa なかった per il passato. 眠れる → 眠れない → 眠れなかった, «non sono riuscito a dormire».'),
  ('03e003e9-bc42-5550-98fa-1a83f70cbce6', '可能形', 'assemble', '{"sentence":{"kanji":"日曜日は友達に会えない","kana":"にちようびはともだちにあえない"},"answer":["日曜日は","友達に","会えない"],"prompt":{"en":"Build: \"On Sunday I can''t meet my friends.\"","it":"Componi: «Domenica non posso vedere i miei amici.»"},"translation":{"en":"On Sunday I can''t meet my friends.","it":"Domenica non posso vedere i miei amici."},"glosses":[{"text":"日曜日は","reading":"にちようびは","meaning":{"en":"on Sunday (topic)","it":"domenica (tema)"}},{"text":"友達に","reading":"ともだちに","meaning":{"en":"friends (whom you meet)","it":"gli amici (chi si vede)"}},{"text":"会えない","reading":"あえない","meaning":{"en":"can''t meet","it":"non poter vedere"}}]}'::jsonb, '可能形', '会う ("meet") → 会える ("can meet", the potential form) → 会えない ("can''t meet"). The person you meet takes に: 友達に会う. 日曜日 is the topic here (what we are talking about), so it takes は.', '会う («incontrare») → 会える («poter incontrare», la forma potenziale) → 会えない («non poter incontrare»). La persona che incontri prende に: 友達に会う. Qui 日曜日 è il tema (ciò di cui si parla), quindi prende は.'),
  ('0239c596-9ece-5ceb-a7fb-7bd19a34c098', '可能形', 'single-select', '{"sentence":{"kanji":"明日は来られる","kana":"あしたはこられる"},"answer":"来られる","distractors":["来えれる","来れられる","来られれる"],"gap":{"kanji":"明日は＿","kana":"あしたは＿"},"prompt":{"en":"\"I can come tomorrow.\" What is the potential form of 来る (\"come\")?","it":"«Domani posso venire.» Qual è la forma potenziale di 来る («venire»)?"},"translation":{"en":"I can come tomorrow.","it":"Domani posso venire."},"glosses":[{"text":"来られる","reading":"こられる"},{"text":"来れられる","reading":"これられる"},{"text":"来られれる","reading":"こられれる"},{"text":"来えれる","reading":"こえれる"}]}'::jsonb, '不規則動詞の可能形', '来る ("to come") is irregular. Its potential form ("can come") is 来られる, read こられる: the kanji stays the same, but its reading changes from く to こ. The only other irregular verb is する, whose potential is できる.', '来る («venire») è irregolare. La sua forma potenziale («poter venire») è 来られる, letto こられる: il kanji resta uguale, ma la lettura passa da く a こ. L''unico altro verbo irregolare è する, il cui potenziale è できる.'),
  ('b898bda1-619c-58e6-98ba-28d15df1918c', '可能形', 'select-span', '{"sentence":{"kanji":"カタカナが書ける","kana":"カタカナがかける"},"answer":{"start":2,"end":3},"prompt":{"en":"Which part turns 書く (\"write\") into \"can write\"?","it":"Quale parte trasforma 書く («scrivere») in «saper scrivere»?"},"translation":{"en":"I can write katakana.","it":"So scrivere il katakana."},"glosses":[{"text":"カタカナが","meaning":{"en":"katakana + が (what you can write)","it":"katakana + が (ciò che sai scrivere)"}},{"text":"書","reading":"か","meaning":{"en":"write (kanji of 書く)","it":"scrivere (kanji di 書く)"}},{"text":"ける","meaning":{"en":"end of the verb 書ける","it":"fine del verbo 書ける"}}]}'::jsonb, '可能形', 'Select ける. 書く is a godan verb (its last kana changes): the final く becomes け and る is added, 書ける, "can write". This ending is the potential form, the verb form that means "can do".', 'Seleziona ける. 書く è un verbo godan (il suo ultimo kana cambia): la く finale diventa け e si aggiunge る, 書ける, «saper scrivere». Questa desinenza è la forma potenziale, la forma del verbo che dice «posso fare».'),
  ('3f4da328-ca65-57c9-90ef-ce224e87939b', '可能形', 'assemble', '{"sentence":{"kanji":"私は漢字がまだ読めない","kana":"わたしはかんじがまだよめない"},"answer":["私は","漢字が","まだ","読めない"],"prompt":{"en":"Build: \"I still can''t read kanji.\"","it":"Componi: «Non so ancora leggere i kanji.»"},"translation":{"en":"I still can''t read kanji.","it":"Non so ancora leggere i kanji."},"glosses":[{"text":"私は","reading":"わたしは","meaning":{"en":"I (topic)","it":"io (tema)"}},{"text":"漢字が","reading":"かんじが","meaning":{"en":"kanji + が (what you can''t read)","it":"kanji + が (ciò che non sai leggere)"}},{"text":"まだ","meaning":{"en":"still, not yet","it":"ancora"}},{"text":"読めない","reading":"よめない","meaning":{"en":"can''t read","it":"non saper leggere"}}]}'::jsonb, '可能形と「が」', '読める is the potential form of 読む ("can read"), and 読めない is its negative, "can''t read". A potential form describes an ability, so the thing read takes が: 漢字が. まだ with a negative means "not yet".', '読める è la forma potenziale di 読む («saper leggere»), e 読めない è la sua negazione, «non saper leggere». Una forma potenziale descrive una capacità, quindi la cosa letta prende が: 漢字が. まだ con una negazione significa «non ancora».'),
  ('7f6a7bab-f5c1-5cab-a1a7-91ff60493323', '可能形', 'assemble', '{"sentence":{"kanji":"友達もパーティーに来られる","kana":"ともだちもパーティーにこられる"},"answer":["友達も","パーティーに","来られる"],"prompt":{"en":"Build: \"My friends can come to the party too.\"","it":"Componi: «Anche i miei amici possono venire alla festa.»"},"translation":{"en":"My friends can come to the party too.","it":"Anche i miei amici possono venire alla festa."},"glosses":[{"text":"友達も","reading":"ともだちも","meaning":{"en":"friends too","it":"anche gli amici"}},{"text":"パーティーに","meaning":{"en":"to the party","it":"alla festa"}},{"text":"来られる","reading":"こられる","meaning":{"en":"can come","it":"poter venire"}}]}'::jsonb, '不規則動詞の可能形', '来る ("come") is irregular: its potential form ("can come") is 来られる, read こられる. The place you come to takes に: パーティーに. も after 友達 means "too" and takes the place of が.', '来る («venire») è irregolare: la sua forma potenziale («poter venire») è 来られる, letto こられる. Il luogo dove si viene prende に: パーティーに. も dopo 友達 significa «anche» e prende il posto di が.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('8b92cea7-e170-59d5-af03-0d9948f66eec', 'て形で節をつなぐ', 'assemble', '{"sentence":{"kanji":"朝ごはんを食べて学校に行った","kana":"あさごはんをたべてがっこうにいった"},"answer":["朝ごはんを","食べて","学校に","行った"],"prompt":{"en":"Build: \"I ate breakfast and went to school.\"","it":"Componi: «Ho fatto colazione e sono andato a scuola.»"},"translation":{"en":"I ate breakfast and went to school.","it":"Ho fatto colazione e sono andato a scuola."},"glosses":[{"text":"朝ごはんを","reading":"あさごはんを","meaning":{"en":"breakfast + を (what is eaten)","it":"colazione + を (ciò che si mangia)"}},{"text":"食べて","reading":"たべて","meaning":{"en":"eat, and then","it":"mangiare, e poi"}},{"text":"学校に","reading":"がっこうに","meaning":{"en":"to school","it":"a scuola"}},{"text":"行った","reading":"いった","meaning":{"en":"went","it":"sono andato"}}]}'::jsonb, 'て形で節をつなぐ', '食べて is the te-form of 食べる: the verb form ending in て/で that links one action to the next, like "and then". The te-form has no tense of its own: the past た at the end, 行った, makes both actions past.', '食べて è la forma in て di 食べる: la forma del verbo in て/で che collega un''azione alla successiva, come «e poi». La forma in て non ha un tempo suo: il passato た in fondo, 行った, rende passate entrambe le azioni.'),
  ('5037d864-083c-5c3d-babd-d31145d5d7c1', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"窓を開けて外を見た","kana":"まどをあけてそとをみた"},"answer":"開けて","distractors":["開けって","開きて","開けるて"],"gap":{"kanji":"窓を＿外を見た","kana":"まどを＿そとをみた"},"prompt":{"en":"\"I opened the window and looked outside.\" Which form of 開ける (\"open\") links the two actions?","it":"«Ho aperto la finestra e ho guardato fuori.» Quale forma di 開ける («aprire») collega le due azioni?"},"translation":{"en":"I opened the window and looked outside.","it":"Ho aperto la finestra e ho guardato fuori."},"glosses":[{"text":"開けて","reading":"あけて"},{"text":"開けるて","reading":"あけるて"},{"text":"開けって","reading":"あけって"},{"text":"開きて","reading":"あきて"}]}'::jsonb, 'て形で節をつなぐ', 'The te-form (the verb form in て/で) links one action to the next. 開ける is an ichidan verb (it ends in -eru and simply drops る), so 開ける → 開けて. Only the last verb, 見た, is in the past, and that covers both actions.', 'La forma in て (la forma del verbo in て/で) collega un''azione alla successiva. 開ける è un verbo ichidan (finisce in -eru e perde semplicemente る), quindi 開ける → 開けて. Solo l''ultimo verbo, 見た, è al passato, e vale per entrambe le azioni.'),
  ('ade2203c-7d24-5132-8eb2-3fd07457c52b', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"友達が私の宿題を手伝ってくれた","kana":"ともだちがわたしのしゅくだいをてつだってくれた"},"answer":"くれた","distractors":["あげた"],"gap":{"kanji":"友達が私の宿題を手伝って＿","kana":"ともだちがわたしのしゅくだいをてつだって＿"},"prompt":{"en":"\"A friend helped me with my homework.\" Which verb says the favour was done for me?","it":"«Un amico mi ha aiutato con i compiti.» Quale verbo dice che il favore è stato fatto a me?"},"translation":{"en":"A friend helped me with my homework.","it":"Un amico mi ha aiutato con i compiti."}}'::jsonb, '恩恵を受ける「てくれる」', 'The te-form of a verb (here 手伝って, from 手伝う "help") + くれる means someone does something for me, or for my family or group: 手伝ってくれた, "helped me". あげる works the other way, from me to others, so it is wrong when the favour comes to me.', 'La forma in て di un verbo (qui 手伝って, da 手伝う «aiutare») + くれる significa che qualcuno fa qualcosa per me, o per la mia famiglia o il mio gruppo: 手伝ってくれた, «mi ha aiutato». あげる va nell''altro senso, da me agli altri, quindi è sbagliato quando il favore arriva a me.'),
  ('c2fb3ce9-039f-5f33-81e5-87058ea852c3', 'て形で節をつなぐ', 'select-span', '{"sentence":{"kanji":"父が夕飯を作ってくれた","kana":"ちちがゆうはんをつくってくれた"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part says the dinner was made for the speaker?","it":"Quale parte dice che la cena è stata preparata per chi parla?"},"translation":{"en":"My father made dinner for me.","it":"Mio padre mi ha preparato la cena."},"glosses":[{"text":"父が夕飯を作","reading":"ちちがゆうはんをつく","meaning":{"en":"father + が, dinner + を, first part of 作る, \"make\"","it":"padre + が, cena + を, inizio di 作る, «preparare»"}},{"text":"ってくれた","meaning":{"en":"end of 作って + くれた, \"did for me\"","it":"fine di 作って + くれた, «ha fatto per me»"}}]}'::jsonb, '恩恵を受ける「てくれる」', 'Select ってくれた: 作って is the te-form of 作る ("make"), and くれた means "did for me". Together they say the dinner was made for the speaker, with no need for a word meaning "for me".', 'Seleziona ってくれた: 作って è la forma in て di 作る («preparare»), e くれた significa «ha fatto per me». Insieme dicono che la cena è stata preparata per chi parla, senza bisogno di una parola per «per me».'),
  ('9cfd0154-9276-5de8-8f67-efcf5be968fe', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"私は妹に絵本を読んであげた","kana":"わたしはいもうとにえほんをよんであげた"},"answer":"あげた","distractors":["くれた"],"gap":{"kanji":"私は妹に絵本を読んで＿","kana":"わたしはいもうとにえほんをよんで＿"},"prompt":{"en":"\"I read a picture book to my younger sister.\" Which verb says I did it for her?","it":"«Ho letto un libro illustrato a mia sorella minore.» Quale verbo dice che l''ho fatto per lei?"},"translation":{"en":"I read a picture book to my younger sister.","it":"Ho letto un libro illustrato a mia sorella minore."}}'::jsonb, '恩恵を与える「てあげる」', 'The te-form of a verb (here 読んで, from 読む "read") + あげる means I, or someone, do something for another person: 読んであげた, "read to her, for her sake". くれる is only for favours that come toward me.', 'La forma in て di un verbo (qui 読んで, da 読む «leggere») + あげる significa che io, o qualcuno, faccio qualcosa per un''altra persona: 読んであげた, «le ho letto, per lei». くれる è solo per i favori che arrivano a me.'),
  ('25d90831-d6f2-5de8-9121-c357c506b9c6', 'て形で節をつなぐ', 'assemble', '{"sentence":{"kanji":"兄は忙しくて手伝ってくれなかった","kana":"あにはいそがしくててつだってくれなかった"},"answer":["兄は","忙しくて","手伝ってくれなかった"],"prompt":{"en":"Build: \"My older brother was busy and didn''t help me.\"","it":"Componi: «Mio fratello maggiore era impegnato e non mi ha aiutato.»"},"translation":{"en":"My older brother was busy and didn''t help me.","it":"Mio fratello maggiore era impegnato e non mi ha aiutato."},"glosses":[{"text":"兄は","reading":"あには","meaning":{"en":"older brother (topic)","it":"fratello maggiore (tema)"}},{"text":"忙しくて","reading":"いそがしくて","meaning":{"en":"was busy, and so","it":"era impegnato, e quindi"}},{"text":"手伝ってくれなかった","reading":"てつだってくれなかった","meaning":{"en":"didn''t help me","it":"non mi ha aiutato"}}]}'::jsonb, '恩恵を受ける「てくれる」', 'い-adjectives (describing words ending in い) have a te-form too: 忙しい → 忙しくて, here meaning "was busy, so…". 手伝ってくれなかった is the negative past of てくれる: "didn''t help me". The tense at the very end covers both parts.', 'Anche gli aggettivi in い (parole che descrivono e finiscono in い) hanno una forma in て: 忙しい → 忙しくて, qui «era impegnato, quindi…». 手伝ってくれなかった è il passato negativo di てくれる: «non mi ha aiutato». Il tempo in fondo alla frase vale per entrambe le parti.'),
  ('312afbbc-b8f0-59ee-a09e-6e8eb342a12c', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"駅まで歩いて電車に乗った","kana":"えきまであるいてでんしゃにのった"},"answer":"歩いて","distractors":["歩きて","歩って","歩くて"],"gap":{"kanji":"駅まで＿電車に乗った","kana":"えきまで＿でんしゃにのった"},"prompt":{"en":"\"I walked to the station and got on the train.\" Which form of 歩く (\"walk\") links the two actions?","it":"«Sono andato a piedi alla stazione e ho preso il treno.» Quale forma di 歩く («camminare») collega le due azioni?"},"translation":{"en":"I walked to the station and got on the train.","it":"Sono andato a piedi alla stazione e ho preso il treno."},"glosses":[{"text":"歩いて","reading":"あるいて"},{"text":"歩きて","reading":"あるきて"},{"text":"歩って","reading":"あるって"},{"text":"歩くて","reading":"あるくて"}]}'::jsonb, 'て形で節をつなぐ', 'The te-form (the verb form in て/で) links one action to the next. 歩く is a godan verb (its last kana changes) ending in く, and these make the te-form with いて: 歩く → 歩いて. The past た of 乗った, at the end, makes both actions past.', 'La forma in て (la forma del verbo in て/で) collega un''azione alla successiva. 歩く è un verbo godan (il suo ultimo kana cambia) che finisce in く, e questi fanno la forma in て con いて: 歩く → 歩いて. Il passato た di 乗った, in fondo, rende passate entrambe le azioni.'),
  ('0eb60d4f-ce2d-5ac5-997e-c8e0001041c6', 'て形で節をつなぐ', 'select-span', '{"sentence":{"kanji":"シャワーをあびて寝た","kana":"シャワーをあびてねた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the first of the two actions?","it":"Quale parte è la prima delle due azioni?"},"translation":{"en":"I took a shower and went to bed.","it":"Ho fatto la doccia e sono andato a letto."},"glosses":[{"text":"シャワーをあびて","meaning":{"en":"take a shower, and then","it":"fare la doccia, e poi"}},{"text":"寝","reading":"ね","meaning":{"en":"sleep, go to bed (kanji of 寝る)","it":"dormire, andare a letto (kanji di 寝る)"}},{"text":"た","meaning":{"en":"past ending: 寝た","it":"desinenza del passato: 寝た"}}]}'::jsonb, 'て形で節をつなぐ', 'Select シャワーをあびて. あびて is the te-form of あびる ("take a shower"): the verb form in て that links one action to the next, "and then". The second action is 寝た, "went to bed", and its past た covers both.', 'Seleziona シャワーをあびて. あびて è la forma in て di あびる («fare la doccia»): la forma del verbo in て che collega un''azione alla successiva, «e poi». La seconda azione è 寝た, «sono andato a letto», e il suo passato た vale per entrambe.'),
  ('66d19244-8c4c-5e90-815e-c203337c0c72', 'て形で節をつなぐ', 'select-span', '{"sentence":{"kanji":"母に花を買ってあげた","kana":"ははにはなをかってあげた"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part says I did it for someone else?","it":"Quale parte dice che l''ho fatto per qualcun altro?"},"translation":{"en":"I bought flowers for my mother.","it":"Ho comprato dei fiori per mia madre."},"glosses":[{"text":"母に花を買","reading":"ははにはなをか","meaning":{"en":"mother + に (for whom), flowers + を, first part of 買う, \"buy\"","it":"madre + に (per chi), fiori + を, inizio di 買う, «comprare»"}},{"text":"ってあげた","meaning":{"en":"end of 買って + あげた, \"did for someone\"","it":"fine di 買って + あげた, «ho fatto per qualcuno»"}}]}'::jsonb, '恩恵を与える「てあげる」', 'Select ってあげた: 買って is the te-form of 買う ("buy"), and あげた means "did for someone". Together they say I bought the flowers for my mother''s sake. The person who receives the favour takes に: 母に.', 'Seleziona ってあげた: 買って è la forma in て di 買う («comprare»), e あげた significa «ho fatto per qualcuno». Insieme dicono che ho comprato i fiori per mia madre. La persona che riceve il favore prende に: 母に.'),
  ('48249e92-0897-59d2-a709-9ddf88e4a483', 'て形で節をつなぐ', 'assemble', '{"sentence":{"kanji":"弟に傘を貸してあげた","kana":"おとうとにかさをかしてあげた"},"answer":["弟に","傘を","貸してあげた"],"prompt":{"en":"Build: \"I lent my umbrella to my younger brother.\"","it":"Componi: «Ho prestato l''ombrello a mio fratello minore.»"},"translation":{"en":"I lent my umbrella to my younger brother.","it":"Ho prestato l''ombrello a mio fratello minore."},"glosses":[{"text":"弟に","reading":"おとうとに","meaning":{"en":"to my younger brother","it":"a mio fratello minore"}},{"text":"傘を","reading":"かさを","meaning":{"en":"umbrella + を (what is lent)","it":"ombrello + を (ciò che si presta)"}},{"text":"貸してあげた","reading":"かしてあげた","meaning":{"en":"lent (as a favour)","it":"ho prestato (come favore)"}}]}'::jsonb, '恩恵を与える「てあげる」', '貸して is the te-form of 貸す ("lend"), and あげた adds that I did it for him, as a favour. The person who receives it takes に: 弟に. The thing lent takes を, the particle for the object (the thing the action is done to).', '貸して è la forma in て di 貸す («prestare»), e あげた aggiunge che l''ho fatto per lui, come favore. Chi lo riceve prende に: 弟に. La cosa prestata prende を, la particella dell''oggetto (la cosa su cui cade l''azione).')
